
// ============================================================
// TEST DATA — q: question, o: [options a-d], a: correct index,
// r: rationale, ref: Student Guide reference.
// Source: NIFE Engines Practice Tests A/B/C
// (NAVAVSCOLSCOM-SG-200, Unit 3/5, 14SEP2020), including the
// answer key & rationale tables from each test.
// ============================================================
const TESTS = [
{
  name: "Test A — Easy",
  desc: "Single-concept recall drawn directly from Student Guide language.",
  questions: [
    {q:"Total pressure is the sum of:", o:["Static pressure and ambient pressure","Static pressure and dynamic pressure","Dynamic pressure and ram pressure","Ram pressure and ambient pressure"], a:1, r:"Total Pressure = Static Pressure + Dynamic Pressure. Static is potential energy at rest; dynamic is kinetic energy of motion.", ref:"Ch 1, EO 2.11"},
    {q:"The three components common to every gas generator are:", o:["Inlet, compressor, exhaust","Fan, compressor, turbine","Compressor, combustion chamber, turbine","Compressor, diffuser, exhaust"], a:2, r:"Every gas turbine engine contains at minimum a compressor, combustion chamber, and turbine. Inlet/exhaust are added to make a turbojet.", ref:"Ch 1, EO 2.64"},
    {q:"As subsonic airflow passes through a convergent opening, its velocity ______ and its pressure ______.", o:["Increases; decreases","Increases; increases","Decreases; increases","Decreases; decreases"], a:0, r:"Subsonic flow is relatively incompressible and follows Bernoulli's Theorem: convergent = velocity up / pressure down.", ref:"Ch 1, EO 2.61"},
    {q:"The four events of the Brayton cycle occur:", o:["Sequentially, within a single piston","Sequentially, throughout the engine","Simultaneously, within a single piston","Simultaneously, throughout the engine"], a:3, r:"Brayton cycle: intake, compression, combustion, exhaust — occurring simultaneously and throughout the engine.", ref:"Ch 1, EO 2.63"},
    {q:"The four events of the Otto cycle occur:", o:["Simultaneously, throughout the engine","Sequentially, generally within a single piston","Simultaneously, within a single piston","Sequentially, throughout the engine"], a:1, r:"Otto cycle events are the same four but occur sequentially, generally within a single piston.", ref:"Ch 1, EO 2.63"},
    {q:"A diffuser is any shape that causes airflow velocity to ______ and pressure to ______.", o:["Increase; decrease","Decrease; increase","Increase; increase","Remain constant; increase"], a:1, r:"Diffuser = velocity decreases, pressure increases. (Nozzle is the opposite.) Shape depends on flow regime.", ref:"Ch 1, EO 2.62"},
    {q:"Gross thrust is measured under standard day conditions of:", o:["29.92 in-Hg and 15 °C","29.92 in-Hg and 59 °C","14.7 in-Hg and 15 °C","30.00 in-Hg and 0 °C"], a:0, r:"Standard day baseline for gross thrust: 29.92 in-Hg and 15 °C at sea level.", ref:"Ch 1, EO 2.66"},
    {q:"Which cockpit gauge indicates shaft horsepower available to drive a propeller or rotor?", o:["EPR gauge","Tachometer","Torquemeter","ITT gauge"], a:2, r:"The torquemeter indicates shaft horsepower for prop/rotor-driven aircraft. EPR is for turbojets/turbofans.", ref:"Ch 1, EO 2.69"},
    {q:"The inlet duct is normally designed to act as a:", o:["Nozzle, never a diffuser","Diffuser, never a nozzle","Nozzle at subsonic speeds and a diffuser at supersonic speeds","Neither a nozzle nor a diffuser"], a:1, r:"“Inlet ducts are normally designed to act as a diffuser but never as a nozzle.”", ref:"Ch 2, EO 2.70"},
    {q:"The shape of a subsonic inlet duct is:", o:["Convergent","Divergent","Convergent-divergent","Constant area"], a:1, r:"Subsonic airflow is relatively incompressible, so a divergent shape reduces velocity and increases pressure.", ref:"Ch 2, EO 2.70"},
    {q:"One stage of an axial-flow compressor consists of:", o:["An impeller and a diffuser","A rotor and a stator","Two rotors","An inlet guide vane and a rotor"], a:1, r:"Each rotor (rotating airfoil) and stator (stationary airfoil) pair forms one stage.", ref:"Ch 2, EO 2.71"},
    {q:"The three types of compressors used in gas turbine engines are:", o:["Centrifugal, axial, and axial-centrifugal","Centrifugal, axial, and dual-spool axial","Low pressure, high pressure, and interstage","Impeller, rotor, and stator"], a:0, r:"Centrifugal, axial, and axial-centrifugal. Dual-spool is a configuration of axial, not a fourth type.", ref:"Ch 2, EO 2.71"},
    {q:"The three main components of a centrifugal-flow compressor are the:", o:["Rotor, stator, and manifold","Impeller, diffuser, and manifold","Impeller, rotor, and diffuser","Inducer, rotor, and exit guide vane"], a:1, r:"Impeller (rotor inducer) → diffuser → manifold. Impeller raises total pressure; diffuser trades velocity for pressure; manifold routes air to the burner.", ref:"Ch 2, EO 2.71"},
    {q:"Primary air makes up ______ of the airflow entering the combustion chamber and is used for ______.", o:["25%; combustion","75%; combustion","25%; cooling","75%; cooling"], a:0, r:"25% primary air is mixed with fuel for combustion.", ref:"Ch 2, EO 2.72"},
    {q:"Secondary air makes up ______ of the airflow entering the combustion chamber and is used for ______.", o:["25%; cooling and flame control","75%; cooling and flame control","25%; combustion","75%; combustion"], a:1, r:"75% secondary air flows around the chamber and through holes/louvers to cool the walls and control the flame.", ref:"Ch 2, EO 2.72"},
    {q:"The three general types of combustion chambers are:", o:["Can, basket, and annular","Can, annular, and can-annular","Annular, radial, and can-annular","Can, tubular, and shrouded"], a:1, r:"Can, annular, can-annular.", ref:"Ch 2, EO 2.73"},
    {q:"Turbine blades are attached to the rotor shaft by which method?", o:["Welding","Riveting","Fir tree","Dovetail press-fit"], a:2, r:"Fir tree attachment allows blades to expand when heated, preventing cracking at the attachment points. Blades are not welded.", ref:"Ch 2, EO 2.74"},
    {q:"The angle of attack of a compressor rotor blade is the angle between the:", o:["Relative wind and the compressor RPM","Relative wind and the rotor blade chord line","Inlet airflow and the compressor RPM","Stator vane chord line and the inlet airflow"], a:1, r:"AOA is between the relative wind and the rotor blade chord line. Relative wind is formed by compressor RPM + inlet airflow.", ref:"Ch 3, EO 3.11"},
    {q:"Other than mechanical malfunctions, the most common cause of a compressor stall is:", o:["Excessive fuel flow","Airflow distortion","Low oil pressure","High ambient pressure"], a:1, r:"Airflow distortion is the most common cause; mechanical malfunctions are the other main category.", ref:"Ch 3, EO 3.12"},
    {q:"With the PCL held constant, the indications of a compressor stall include:", o:["RPM increase, ITT decrease, and loud bangs","RPM decrease, ITT increase, and loud bangs","RPM increase, ITT increase, and silence","RPM decrease, ITT decrease, and vibration"], a:1, r:"Reduced airflow to the turbine requires more fuel to hold thrust → ITT rise; airflow breakdown → RPM decay; plus possible loud bangs.", ref:"Ch 3, EO 3.12"},
    {q:"Which of the following is an action a pilot can take to avoid a compressor stall?", o:["Make rapid, decisive PCL movements at low airspeed","Increase angle of attack when turbulence is encountered","Avoid abrupt changes in aircraft attitude and move the PCL smoothly","Reduce airspeed below the prescribed minimum"], a:2, r:"Avoid erratic/abrupt PCL movement, maintain minimum airspeed, avoid abrupt attitude changes and severe turbulence.", ref:"Ch 3, EO 3.14"},
    {q:"Thrust specific fuel consumption (TSFC) is defined as:", o:["The amount of thrust produced per gallon of fuel","The amount of fuel required to produce one pound of thrust","The number of miles flown per pound of fuel","The amount of air required to produce one pound of thrust"], a:1, r:"TSFC = the amount of fuel required to produce one pound of thrust.", ref:"Ch 4, EO 2.83"},
    {q:"A turbojet derives its thrust by:", o:["Slightly accelerating a large mass of air","Highly accelerating a small mass of air","Slightly accelerating a small mass of air","Converting nearly all energy into shaft horsepower"], a:1, r:"The turbojet highly accelerates a small mass of air; all inlet air traverses the gas generator.", ref:"Ch 4, EO 2.79"},
    {q:"On a turbofan engine, the fan typically produces what percentage of total thrust?", o:["10%","30–60%","75%","90%"], a:1, r:"The fan supplies 30–60% of total thrust; the gas generator exhaust supplies the remaining 40–70%.", ref:"Ch 4, EO 2.81"},
    {q:"In a turboprop engine, approximately 90% of the thrust is produced by the:", o:["Exhaust gases","Ducted fan","Propeller","Free turbine"], a:2, r:"The propeller produces ~90% of turboprop thrust; exhaust gases produce the other ~10%.", ref:"Ch 4, EO 2.88"},
    {q:"The percentage of a turboshaft engine's thrust that comes from the exhaust is:", o:["25%","40–70%","10%","Virtually none"], a:3, r:"In a turboshaft the free/power turbine extracts virtually all remaining energy; exhaust thrust is negligible.", ref:"Ch 4, EO 2.92"},
    {q:"The reduction gear box converts:", o:["High RPM and low torque into low RPM and high torque","Low RPM and high torque into high RPM and low torque","Mechanical energy into electrical energy","High torque into shaft horsepower"], a:0, r:"The RGB is a one-speed transmission converting high RPM/low torque to low RPM/high torque, keeping blade tips subsonic.", ref:"Ch 4, EO 2.89"},
    {q:"As bypass ratio increases, TSFC:", o:["Increases","Decreases","Remains constant","Is unaffected"], a:1, r:"Higher bypass ratio yields a lower TSFC — an inverse relationship. The most fuel-efficient engines have the highest bypass ratios.", ref:"Ch 4, EO 2.87"},
    {q:"What single component is added to a gas generator to make it a turbofan?", o:["A reduction gear box","A free turbine","A ducted fan","An afterburner"], a:2, r:"A duct-enclosed fan driven by the gas generator, accelerating a large mass of air around the core.", ref:"Ch 4, EO 2.81"},
    {q:"Pascal's Law states that pressure applied to a confined liquid is transmitted:", o:["Equally in all directions without loss and acts with equal force on equal surfaces","Equally in all directions with a loss of pressure proportional to distance","Only in the direction of the applied force","Equally in all directions and acts with unequal force on equal surfaces"], a:0, r:"Pressure applied to a confined liquid is transmitted equally in all directions without loss of pressure and acts with equal force on equal surfaces.", ref:"Ch 5, EO 2.94"},
    {q:"The main purpose of an aircraft hydraulic system is to multiply:", o:["Pressure","Work","Force","Power"], a:2, r:"Hydraulic systems multiply force; the trade is linear displacement.", ref:"Ch 5, EO 2.96"},
    {q:"The purpose of an actuator is to:", o:["Direct the flow of fluid to the desired working port","Convert fluid under pressure into mechanical motion","Absorb pressure surges in the system","Prevent excessive fluid loss from a leak"], a:1, r:"Actuators convert fluid under pressure into linear or reciprocating mechanical motion. (a) is the selector valve; (c) the accumulator; (d) the hydraulic fuse.", ref:"Ch 5, EO 2.96"},
    {q:"Many military aircraft hydraulic systems operate at approximately:", o:["300 PSI","1,000 PSI","3,000 PSI","10,000 PSI"], a:2, r:"Most military hydraulic systems operate near 3,000 PSI.", ref:"Ch 5, EO 2.96"},
    {q:"A transformer rectifier (TR) converts:", o:["AC power into DC power","DC power into AC power","Mechanical energy into AC power","Mechanical energy into DC power"], a:0, r:"TR: AC in, DC out.", ref:"Ch 6, EO 2.98"},
    {q:"An inverter converts:", o:["AC power into DC power","DC power into AC power","Mechanical energy into electrical energy","High voltage into low voltage"], a:1, r:"Inverter: DC in, AC out — the backup AC source if the AC generator fails.", ref:"Ch 6, EO 2.98"},
    {q:"The constant speed drive (CSD) is used to:", o:["Maintain a constant engine RPM regardless of PCL position","Maintain a constant generator input RPM regardless of engine RPM","Maintain a constant aircraft true airspeed","Limit generator output to 100%"], a:1, r:"The CSD is a hydromechanical linkage between engine and generator ensuring constant generator input RPM, and therefore steady voltage output.", ref:"Ch 6, EO 2.98"},
    {q:"The bus that routes power to equipment required for flight safety is the:", o:["Primary bus","Monitor bus","Essential bus","Starter bus"], a:2, r:"Essential bus = flight safety (e.g., primary attitude gyro). Primary = mission equipment; monitor/secondary = convenience; starter = engine start.", ref:"Ch 6, EO 2.98"},
    {q:"JP-5 is used for shipboard operations because of its high:", o:["Volatility","Flash point","Octane rating","Vapor pressure"], a:1, r:"JP-5 has a high flash point (140 °F) and low volatility, meeting Naval shipboard storage safety requirements.", ref:"Ch 7, EO 2.102"},
    {q:"Volatility is defined as:", o:["A liquid's resistance to flow","The measurement of a liquid's ability to convert to a vaporous state","The lowest temperature at which a fuel will ignite with a momentary flame","The energy content of a fuel per gallon"], a:1, r:"Volatility = the measurement of a liquid's ability to convert to a vaporous state. (c) defines flash point; (a) defines viscosity.", ref:"Ch 7, EO 2.99"},
    {q:"Which component is considered the “brain” of the engine fuel system?", o:["The boost pump","The pressurizing and dump valve","The fuel control unit","The engine-driven pump"], a:2, r:"The FCU is the “brain” of the engine fuel system — it computes and meters fuel flow.", ref:"Ch 7, EO 2.103"},
    {q:"Avgas 100LL is dyed:", o:["Green","Blue","Red","Clear"], a:1, r:"Avgas 100LL (low lead) is dyed blue; Avgas 100 is dyed green.", ref:"Ch 7, EO 2.102"},
    {q:"The fuel-flow gauge indicates fuel consumption in:", o:["Gallons per hour","Pounds per square inch","Pounds per hour","Pounds per minute"], a:2, r:"The fuel-flow transmitter at the FCU outlet drives a cockpit gauge reading in pounds per hour (PPH).", ref:"Ch 7, EO 2.103"},
    {q:"Viscosity is defined as:", o:["A fluid's tendency to evaporate at a given temperature","The property of a fluid that resists the force tending to cause it to flow","A fluid's ability to dissipate heat","The lowest temperature at which a fluid will ignite"], a:1, r:"Viscosity = resistance to flow. It is inversely related to temperature.", ref:"Ch 8, EO 2.107"},
    {q:"The three subsystems of a dry sump lubrication system are:", o:["Pressure, scavenge, and delivery","Pressure, scavenge, and breather pressurizing","Delivery, return, and breather pressurizing","Pressure, return, and cooling"], a:1, r:"Pressure, scavenge, and breather pressurizing.", ref:"Ch 8, EO 2.108"},
    {q:"The synthetic oil most commonly used in current military jet engines is designated:", o:["MIL-L-7808","MIL-L-23699","MIL-H-5606","MIL-L-6082"], a:1, r:"MIL-L-23699 (NATO O-156) is most common. MIL-L-7808 was the first developed and is still in use.", ref:"Ch 8, EO 2.106"},
    {q:"The two basic types of oil coolers are the:", o:["Air-oil cooler and the fuel-oil heat exchanger","Air-oil cooler and the oil-water radiator","Fuel-oil heat exchanger and the hydraulic-oil cooler","Ram-air cooler and the bleed-air cooler"], a:0, r:"Air-oil cooler and fuel-oil heat exchanger; the fuel-oil type is the most common.", ref:"Ch 8, EO 2.108"},
    {q:"The correct gas turbine engine starting sequence is:", o:["Fuel, ignition, airflow","Ignition, airflow, fuel","Airflow, ignition, fuel","Airflow, fuel, ignition"], a:2, r:"Establish airflow (starter spins compressor) → ignition → fuel. Sequence prevents an explosion at light-off.", ref:"Ch 9, EO 5.1"},
    {q:"The most dangerous type of abnormal start is a:", o:["Hot start","Hung start","False start","Wet start"], a:3, r:"A wet start — fuel-air does not light off initially but retains the capability to ignite. It is an ignition problem and the most dangerous abnormal start.", ref:"Ch 9, EO 5.2"},
    {q:"The most common type of starter used on large gas turbine engines is the:", o:["DC electric motor starter","Air turbine starter","Cartridge starter","Hydraulic starter"], a:1, r:"The air turbine (pneumatic) starter is most common on large engines; the DC electric motor is most common on small engines.", ref:"Ch 9, EO 5.4"},
    {q:"A gas turbine engine is normally provided with how many ignitor plugs?", o:["One per engine","Two per engine","Four per engine","One per combustion chamber"], a:1, r:"Normally two ignitor plugs per engine. On can and can-annular chambers, the plugs are in separate chambers, with flame tubes propagating the flame.", ref:"Ch 9, EO 5.5"}
  ]
},
{
  name: "Test B — Medium",
  desc: "Two-part stems, applied relationships, and plausible near-miss distractors.",
  questions: [
    {q:"When a compressible fluid passes through a divergent opening, its velocity ______ and its pressure ______.", o:["Decreases; increases","Increases; decreases","Increases; increases","Decreases; decreases"], a:1, r:"“Compressible” = supersonic, which acts opposite to Bernoulli's Theorem. Supersonic + divergent = velocity up / pressure down.", ref:"Ch 1, EO 2.61"},
    {q:"The shape of a supersonic diffuser is ______ while the shape of a subsonic nozzle is ______.", o:["Divergent; divergent","Divergent; convergent","Convergent; convergent","Convergent; divergent"], a:2, r:"A diffuser always does velocity down / pressure up; supersonic flow requires a convergent shape to do that. A nozzle always does velocity up / pressure down; subsonic flow requires a convergent shape. Both convergent.", ref:"Ch 1, EO 2.61/2.62"},
    {q:"As airflow traverses a turbojet, velocity ______ through the compressor, ______ through the burner, and ______ through the turbine.", o:["Increases; increases; decreases","Remains fairly constant; increases; increases","Decreases; increases; decreases","Remains fairly constant; decreases; increases"], a:1, r:"Velocity remains fairly constant through the compressor (cross-sectional area decreases as pressure rises), then increases through the burner and turbine.", ref:"Ch 1, EO 2.65"},
    {q:"Gross thrust and net thrust are equal when:", o:["The aircraft is at its optimum cruise altitude","Inlet airflow velocity is zero and conditions are standard day","Exhaust velocity equals inlet velocity","The engine is operating at military rated thrust"], a:1, r:"Net thrust corrects for inlet velocity; when that velocity is zero and conditions are standard, the two measurements coincide.", ref:"Ch 1, EO 2.66"},
    {q:"An increase in ambient air temperature will cause thrust to ______ because air density ______.", o:["Increase; increases","Increase; decreases","Decrease; decreases","Decrease; increases"], a:2, r:"Higher temperature → molecules move apart → density decreases → mass flow decreases → thrust decreases (may vary up to 20% from standard rated thrust).", ref:"Ch 1, EO 2.67"},
    {q:"As an aircraft climbs, thrust decreases because:", o:["Temperature drops faster than pressure drops","The pressure drop outweighs the thrust increase gained from the temperature drop","Ram effect is eliminated above 20,000 feet","Engine RPM must be reduced with altitude"], a:1, r:"Both pressure and temperature drop with altitude. The pressure-driven thrust loss is greater than the temperature-driven thrust gain, so net thrust decreases.", ref:"Ch 1, EO 2.67"},
    {q:"Considering ram effect, an increase in airspeed produces ______ at subsonic speeds and ______ at supersonic speeds.", o:["A significant thrust increase; a slight thrust decrease","A neutral effect or slight thrust increase; a significant thrust increase","A significant thrust decrease; a neutral effect","No change; no change"], a:1, r:"More air is rammed into the inlet, increasing mass and offsetting the reduced acceleration — neutral or slightly positive subsonic, significantly positive supersonic.", ref:"Ch 1, EO 2.68"},
    {q:"The EPR gauge is found on ______ and indicates ______.", o:["Turboprops and turboshafts; shaft horsepower available","Turbojets and turbofans; the pressure ratio between inlet and exhaust airflow","All gas turbine engines; percent RPM","Turbojets and turbofans; the temperature ratio across the turbine"], a:1, r:"EPR indicates the pressure ratio between inlet and exhaust airflow, used on engines relying on exhaust gas propulsion (turbojet/turbofan). Torquemeters serve turboprop/turboshaft.", ref:"Ch 1, EO 2.69"},
    {q:"In the compressor section, both velocity and pressure increase. This is possible because:", o:["The compressor is a closed system and Bernoulli's Theorem is suspended","The compressor receives energy from the turbine via the drive shaft, so it is not a closed system","Airflow becomes supersonic within the compressor","The stators add energy to the airflow"], a:1, r:"Because the turbine feeds energy in through the drive shaft, the compressor is not a closed system — velocity and pressure both rise, so total pressure increases.", ref:"Ch 2, EO 2.71"},
    {q:"In a centrifugal-flow compressor, the impeller ______ while the diffuser ______.", o:["Increases velocity and pressure; decreases velocity and increases pressure","Increases velocity only; increases velocity and pressure","Decreases velocity and increases pressure; increases velocity and pressure","Increases pressure only; decreases pressure and increases velocity"], a:0, r:"Impeller: increases velocity and pressure → total pressure increases. Diffuser: stationary, adds no energy → velocity down, pressure up, total pressure unchanged.", ref:"Ch 2, EO 2.71"},
    {q:"Rotor and stator blades decrease in length from the front to the rear of an axial compressor in order to:", o:["Reduce total engine weight aft of the compressor","Allow velocity to remain fairly constant as pressure increases","Increase velocity progressively through each stage","Prevent the blade tips from exceeding supersonic speed"], a:1, r:"Cross-sectional area decreases fore-to-aft so velocity stays fairly constant while pressure rises; shorter blades follow from the smaller annulus. If velocity dropped excessively aft, the stall region would be approached.", ref:"Ch 2, EO 2.71"},
    {q:"From forward to aft, the correct order of components in a dual-spool axial flow engine is:", o:["Low pressure compressor, high pressure compressor, low pressure turbine, high pressure turbine","High pressure compressor, low pressure compressor, high pressure turbine, low pressure turbine","Low pressure compressor, high pressure compressor, high pressure turbine, low pressure turbine","Low pressure turbine, high pressure turbine, low pressure compressor, high pressure compressor"], a:2, r:"LP compressor → HP compressor → HP turbine → LP turbine. The HP turbine sits directly behind the burner and drives the HP compressor.", ref:"Ch 2, EO 2.71"},
    {q:"Inlet guide vanes ______ while exit guide vanes ______.", o:["Straighten the airflow for the diffuser; impart a swirl in the direction of engine rotation","Impart a swirl in the direction of engine rotation; straighten the airflow for the diffuser","Increase airflow velocity; decrease airflow velocity","Meter airflow into the compressor; meter airflow into the burner"], a:1, r:"IGVs impart swirl in the direction of engine rotation to reduce drag on the first-stage rotor. Exit (straightening) guide vanes are the last stators, preparing airflow for the diffuser.", ref:"Ch 2, EO 2.71"},
    {q:"A primary disadvantage of the can type combustion chamber is:", o:["It cannot be removed without disassembling the engine from the aircraft","It has the highest cost of the three designs","It produces uneven heat distribution and possible cold spots at the turbine inlet","Its large-diameter, thin-wall cylinder creates structural problems"], a:2, r:"Because each can directly adjoins the turbine section, a malfunction produces non-uniform temperature distribution (cold spots) and possible turbine damage. (a) and (d) are annular disadvantages; (b) is can-annular.", ref:"Ch 2, EO 2.73"},
    {q:"In the turbine section, the stator vanes come ______ the rotors and serve to ______.", o:["After; convert heat energy into mechanical energy","Before; prepare the airflow and deflect the gases in the direction of turbine wheel rotation","After; straighten the swirling gas flow leaving the turbine","Before; increase the static pressure of the gases before they strike the rotors"], a:1, r:"Turbine stators precede the rotors, prepare the airflow for power extraction, and deflect the gases at a specific angle in the direction of turbine wheel rotation.", ref:"Ch 2, EO 2.74"},
    {q:"The three or four radial hollow struts in the exhaust section:", o:["Support the inner cone and straighten the swirling gas flow exiting the turbine","Introduce fuel to the afterburner duct","Vary the area of the exhaust nozzle","Absorb pressure fluctuations caused by screech"], a:0, r:"The hollow struts support the inner cone from the outer duct and straighten the swirling gas flow leaving the turbine.", ref:"Ch 2, EO 2.76"},
    {q:"Which statement about the afterburner is correct?", o:["Spray bars absorb violent pressure fluctuations and flame holders introduce fuel","The flame holder absorbs violent pressure fluctuations and spray bars create eddies","The screech liner absorbs violent pressure fluctuations and spray bars introduce fuel","The screech liner introduces fuel and the flame holder absorbs pressure fluctuations"], a:2, r:"Screech liners are corrugated/perforated sleeves acting as shock absorbers against pressure fluctuations; spray bars introduce fuel; flame holders create eddies for mixing.", ref:"Ch 2, EO 2.77"},
    {q:"The four mechanical malfunctions that can lead to a compressor stall are:", o:["Variable inlet guide vanes/stator vanes, FCU, FOD, and variable exhaust nozzle","Variable inlet guide vanes/stator vanes, FOD, PCL, and EPR gauge","Angle of attack, FOD, fuel control unit, and variable exhaust nozzle","Bleed valves, dual-spool compressor, FOD, and afterburner"], a:0, r:"“VFFV”: Variable IGV/stator vanes, FCU, FOD, Variable exhaust nozzle. Note (c) is a trap — excessive AOA is the result, not a mechanical malfunction.", ref:"Ch 3, EO 3.13"},
    {q:"The four design features a manufacturer can incorporate to minimize compressor stall are:", o:["Variable inlet guide vanes/stator vanes, dual-spool compressor, bleed valves, variable exhaust nozzle","Fir tree attachment, dual-spool compressor, bleed valves, screech liner","Variable geometry inlet, FCU, FOD screens, variable exhaust nozzle","Bleed valves, inlet guide vanes, exit guide vanes, diffuser"], a:0, r:"“VDBV”: Variable IGV/stator vanes, Dual/twin/split-spool compressor, Bleed valves, Variable exhaust nozzle.", ref:"Ch 3, EO 3.15"},
    {q:"A failure of the FCU can create ______ which leads to ______.", o:["Too lean a fuel mixture; a compressor stall","Too rich a fuel mixture; excessive burner pressure, a back-flow of air, and a compressor stall","Too rich a fuel mixture; a flameout","Excessive back pressure at the nozzle; foreign object damage"], a:1, r:"An over-rich mixture causes excessive burner pressure and a back-flow of air into the compressor. Too lean causes a flameout, not a stall.", ref:"Ch 3, EO 3.13"},
    {q:"Once a compressor stall occurs, the pilot's FIRST reaction should be to:", o:["Retard the PCL to idle","Shut down the engine","Reduce the attitude of the aircraft to reduce the inlet's angle of attack","Manually open the bleed valves"], a:2, r:"Reduce aircraft attitude first — that lowers inlet AOA and restores turbulence-free air. Then retard the PCL to just below stall threshold.", ref:"Ch 3, EO 3.14"},
    {q:"A turbojet is constructed of ______ and produces thrust by ______.", o:["Inlet, gas generator, ducted fan, exhaust; increasing the mass of accelerated airflow","Inlet, gas generator, exhaust; increasing the overall velocity of accelerated airflow","Inlet, gas generator, exhaust; increasing the mass of accelerated airflow","Fan, gas generator, RGB, exhaust; increasing the overall velocity of accelerated airflow"], a:1, r:"Turbojet = basic gas generator plus an inlet and an exhaust section; thrust comes from highly accelerating a small mass (velocity increase).", ref:"Ch 4, EO 2.79"},
    {q:"In a turbofan, the fan may be driven by:", o:["A free/power turbine only","The gas generator turbine only","Either a free/power turbine or the gas generator turbine","The reduction gear box"], a:2, r:"Either a free/power turbine aft of the gas generator turbines, or directly by the gas generator turbine with the fan attached to the compressor.", ref:"Ch 4, EO 2.81"},
    {q:"A modern fighter such as the F/A-18 uses a bypass ratio near ______ while a cargo aircraft uses a ______ bypass ratio.", o:["1:1; higher","6:1; lower","1:1; lower","6:1; higher"], a:0, r:"Fighters/interceptors run low bypass near 1:1 to resemble turbojet performance; cargo and airliner engines run high bypass for low TSFC and heavy takeoff weights.", ref:"Ch 4, EO 2.87"},
    {q:"In a turboprop, the exhaust gases produce approximately what percentage of the total thrust?", o:["None — it is negligible","10%","25%","30–60%"], a:1, r:"~10% from exhaust gases, ~90% from the propeller. “Negligible” (a) describes a turboshaft.", ref:"Ch 4, EO 2.88"},
    {q:"In a torquemeter assembly, the ______ shaft carries the load from the propeller and twists, while the ______ shaft does not twist and provides the reference.", o:["Reference; torque","Torque; reference","Outer; inner","Compressor extension; torque"], a:1, r:"The torque shaft (inner) is coupled to the compressor and connects to the RGB; it carries the propeller load and twists. The reference shaft (outer) does not twist.", ref:"Ch 4, EO 2.90"},
    {q:"The turboprop beta range:", o:["Extends from flight idle to full power and is used in flight","Extends from flight idle to max reverse and is used only during ground operations","Is the normal cruise range for all turboprop aircraft","Is controlled entirely by the propeller governor with no PCL input"], a:1, r:"Beta = ground operations only, flight idle to max reverse, with the PCL mechanically connected to the pitch change assembly. Alpha is the flight range. (The T-6B has no beta range.)", ref:"Ch 4, EO 2.91"},
    {q:"A turboshaft engine consists of two basic sections:", o:["The gas generator and the reduction gear box","The gas generator and the free/power turbine","The compressor section and the torquemeter assembly","The free turbine and the ducted fan"], a:1, r:"Gas generator + free/power turbine. The power turbine is mechanically independent and connects to the main transmission through a coaxial main drive shaft.", ref:"Ch 4, EO 2.92"},
    {q:"A free turbine is best described as a turbine that:", o:["Is directly attached to the compressor drive shaft","Is mechanically independent of the gas generator and located aft of the gas generator turbines","Extracts 75% of the total energy leaving the burner","Is located forward of the gas generator turbines"], a:1, r:"A free turbine is not mechanically connected to the compressor and sits aft of the gas generator turbines.", ref:"Ch 4, EO 2.93"},
    {q:"In a closed hydraulic system, a 20-pound force applied to a 2 square inch input piston will produce how much force on a 20 square inch output piston?", o:["20 pounds","40 pounds","200 pounds","400 pounds"], a:2, r:"P = F/A = 20 lb ÷ 2 in² = 10 PSI. That 10 PSI acts on every square inch of the output piston: 10 × 20 = 200 pounds.", ref:"Ch 5, EO 2.94/2.95"},
    {q:"Which type of hydraulic pump MUST be used in conjunction with a pressure regulator or unloader valve?", o:["Hand pump","Variable displacement pump","Constant displacement pump","Electric motor-driven pump"], a:2, r:"A constant displacement pump delivers constant output regardless of system pressure, so a pressure regulator or unloader valve is required. Variable displacement pumps self-regulate.", ref:"Ch 5, EO 2.96"},
    {q:"The purpose of the hydraulic accumulator is best summarized as:", o:["SEAM — shock absorber, emergency use, assistance in peak operations, maintains pressure in conjunction with the check valve during shutdown","SHAFT — storage, heat dissipation, aeration, foreign matter trap, thermal expansion","SEAM — storage, emergency use, aeration, make pressure during shutdown","SHAFT — shock absorber, heat dissipation, accumulator, foreign matter trap, thermal expansion"], a:0, r:"SEAM belongs to the accumulator; SHAFT belongs to the reservoir. Note the accumulator maintains shutdown pressure in conjunction with the check valve — not the relief valve.", ref:"Ch 5, EO 2.96"},
    {q:"The ______ system supplies fluid pressure to the flight controls AND utility systems, while the ______ system supplies fluid pressure to the flight controls only.", o:["Power control; utility","Utility; power control","Primary control; utility","Utility; primary control"], a:1, r:"The utility system operates landing gear, wing fold, and brakes in addition to the flight controls. Systems dedicated to flight controls only are the power control systems (PC-1, PC-2).", ref:"Ch 5, EO 2.96"},
    {q:"Sources of ______ energy are ______ while sources of ______ energy are ______.", o:["AC; alternator and inverter; DC; generator and transformer rectifier","AC; alternator, TR, and inverter; DC; generator and inverter","DC; alternator and inverter; AC; generator and transformer rectifier","DC; alternator and TR; AC; generator and inverter"], a:0, r:"AC: AC generator (alternator) and inverter. DC: DC generator, battery, and transformer rectifier.", ref:"Ch 6, EO 2.97/2.98"},
    {q:"In the event of a main generator failure, which bus or buses will stay on the line?", o:["The primary and secondary buses","The DC and AC essential buses","All AC buses","The starter bus only"], a:1, r:"The DC and AC essential buses remain powered — they carry the equipment required for flight safety.", ref:"Ch 6, EO 2.98"},
    {q:"Manual interruption of electrical power is provided by ______ while AUTOMATIC circuit protection is provided by ______.", o:["Fuses only; circuit breakers only","Switches and circuit breakers; circuit breakers and fuses","Circuit breakers only; switches and fuses","Warning lights; the master caution panel"], a:1, r:"Switches provide manual control; circuit breakers provide both manual and automatic interruption; fuses provide automatic protection only.", ref:"Ch 6, EO 2.98"},
    {q:"Most modern military aircraft primarily use AC-powered components because AC:", o:["Requires more current, which improves component reliability","Requires less current due to higher voltage and a ground neutral system, allowing smaller wiring and less weight","Can be stored directly in the aircraft battery","Eliminates the need for a constant speed drive"], a:1, r:"Higher voltage plus a ground neutral system means less current, smaller wiring, and less weight; AC generators and control components are also lighter and proven reliable.", ref:"Ch 6, EO 2.97"},
    {q:"As a fuel's volatility RATING increases, its flash point:", o:["Increases","Decreases","Remains constant","Varies with ambient temperature"], a:1, r:"Volatility rating and flash point are inversely related — a more volatile fuel ignites at a lower temperature.", ref:"Ch 7, EO 2.101"},
    {q:"Increasing the temperature of a fuel will ______ its volatility and ______ its flash point.", o:["Increase; increase","Increase; leave unchanged","Decrease; decrease","Increase; decrease"], a:1, r:"Heating a fuel releases more vapor, increasing volatility. Flash point is a fixed property of the fuel and does not change with ambient temperature.", ref:"Ch 7, EO 2.101"},
    {q:"The four operational inputs the FCU computing system senses are:", o:["EPR, RPM, fuel flow, and PCL position","Compressor inlet temperature, RPM, turbine temperature, and PCL position","Ambient pressure, oil pressure, RPM, and PCL position","Compressor inlet temperature, EPR, ITT, and airspeed"], a:1, r:"CIT (measures ambient air density), compressor RPM, turbine temperature (ITT, to prevent turbine damage), and PCL position.", ref:"Ch 7, EO 2.103"},
    {q:"During engine start, the P&D valve is:", o:["Closed, to limit fuel flow to the primary manifold and ensure proper atomization","Open, to drain residual fuel from the manifolds","Open, to ensure proper fuel pressure to the secondary manifold","Closed, to prevent fuel from reaching the FCU"], a:0, r:"Both valves are closed at start: the dump valve is closed by an electrical/pressure signal from the FCU, and the spring-loaded pressurizing valve limits starting flow to the primary manifold for proper atomization.", ref:"Ch 7, EO 2.103"},
    {q:"The only rated thrust with a time limitation is:", o:["Normal rated thrust, 30 minutes","Combat rated thrust, 30 minutes","Military rated thrust, 30 minutes","Military rated thrust, 20 minutes"], a:2, r:"MRT — maximum turbine temperature for a limited time, normally 30 minutes. NRT has no time limit; CRT is afterburner and is not based on turbine temperature limits.", ref:"Ch 7, EO 2.104"},
    {q:"The main advantage of a dry sump lubrication system over a wet sump system is that:", o:["It requires fewer scavenge pumps","A larger oil supply can be carried and oil temperature/viscosity can be readily controlled","It eliminates the need for an oil cooler","It permits the engine to operate without a breather pressurizing subsystem"], a:1, r:"The external tank permits a larger supply and readily controlled temperature; it also lets axial engines keep a small diameter.", ref:"Ch 8, EO 2.108"},
    {q:"Scavenge pump elements have a greater pumping capacity than pressure elements in order to:", o:["Increase oil pressure at the bearings","Prevent back pressure in the system and the accumulation of oil in the bearing sumps","Compensate for the loss of oil through the breather system","Force oil through the fuel-oil heat exchanger"], a:1, r:"Greater scavenge capacity prevents back pressure and stops hot oil from accumulating in the bearing sumps.", ref:"Ch 8, EO 2.108"},
    {q:"______ always goes through the fuel-oil heat exchanger, whereas ______ may not always go through it.", o:["Oil; fuel","Fuel; oil","Fuel; hydraulic fluid","Oil; bleed air"], a:1, r:"If the engine is designed with a fuel-oil cooler, fuel always flows through it. Oil can bypass via the thermostatic oil temperature regulating valve when no cooling is needed.", ref:"Ch 8, EO 2.108"},
    {q:"The fuel temperature sensing switch, located in the fuel outlet line of the fuel-oil heat exchanger:", o:["Displays fuel temperature on a cockpit gauge","Sends an electrical signal to actuate the air-oil cooler doors when fuel temperature is excessive","Bypasses the heat exchanger when oil cooling is not needed","Inhibits engine start when fuel temperature is too low"], a:1, r:"Its job is to sense excessive exiting fuel temperature and electrically actuate the air-oil cooler doors. (c) describes the oil temperature regulating valve.", ref:"Ch 8, EO 2.108"},
    {q:"Interstage bleed air is:", o:["Used to drive accessories because of its steady volume and pressure","Ducted overboard to ensure compressor stability, and is not used to drive accessories","Used exclusively for engine and inlet anti-ice","Extracted after the high pressure compressor for cabin pressurization"], a:1, r:"Interstage bleed air is ducted overboard to prevent compressor stall during low thrust operation. It is not used for accessories because it is unavailable at high thrust and lacks steady volume/pressure.", ref:"Ch 9, EO 2.111"},
    {q:"On a dual-spool axial flow compressor, low pressure bleed air used to drive accessory systems is ported:", o:["Before the low pressure compressor","After the low pressure compressor","After the low pressure turbine","Before the high pressure turbine"], a:1, r:"Low pressure bleed air is extracted between the low pressure and high pressure spools — i.e., after the LP compressor.", ref:"Ch 9, EO 2.111"},
    {q:"In a HUNG start, ______; in a FALSE start, ______.", o:["Turbine temperature continues to rise while compressor RPM stabilizes below normal; compressor RPM stabilizes below normal but turbine temperature remains within limits","Compressor RPM stabilizes below normal but turbine temperature remains within limits; turbine temperature continues to rise while RPM stabilizes below normal","Maximum allowable turbine temperature is exceeded; the fuel-air mixture fails to light off","The fuel-air mixture fails to light off; maximum allowable turbine temperature is exceeded"], a:0, r:"Hung start = rising turbine temperature with RPM stabilized below normal. False start = RPM stabilized below normal with temperature within limits. Hot start = exceeding max turbine temperature; wet start = no initial light-off.", ref:"Ch 9, EO 5.2"},
    {q:"The starter remains engaged after the engine reaches self-accelerating speed in order to:", o:["Charge the aircraft battery before generator cut-in","Furnish torque along with the engine so idle RPM is reached faster, decreasing the potential for an abnormal start","Keep the ignitor plugs energized until the engine stabilizes","Prevent the compressor from exceeding its limiting Mach number"], a:1, r:"Engine and starter working together above self-accelerating speed shortens the time to idle RPM. Starters that drop out too soon may cause an abnormal start.", ref:"Ch 9, EO 5.1"}
  ]
},
{
  name: "Test C — Hard",
  desc: "Multi-step reasoning, cross-chapter integration, and near-miss distractors. Read every stem twice.",
  questions: [
    {q:"Across the burner section of a turbojet, pressure ______, temperature ______, and velocity ______.", o:["Increases; increases; decreases","Decreases; increases; increases","Increases; decreases; increases","Decreases; decreases; increases"], a:1, r:"Across the burner: heat energy is added so temperature and velocity rise, while there is a slight pressure loss (one of the design criteria is to minimize that drop, not eliminate it). This is the classic Temperature/Pressure/Velocity chart question.", ref:"Ch 1, EO 2.65; Ch 2, EO 2.72"},
    {q:"A supersonic inlet duct is convergent-divergent. The CONVERGENT portion exists specifically to:", o:["Accelerate the airflow so it arrives at the compressor at high velocity","Slow the highly compressible supersonic airflow below sonic velocity while raising its pressure","Prevent inlet buzz by expelling the shock wave forward of the duct","Convert the remaining static pressure into supersonic flow"], a:1, r:"Supersonic airflow reaching the compressor would generate shock waves and damage the rotor/stator blades. The convergent section slows the compressible flow below sonic and raises pressure; the divergent section then acts like a subsonic inlet.", ref:"Ch 2, EO 2.70"},
    {q:"Above approximately 36,000 feet, thrust decreases MORE RAPIDLY than it did at lower altitudes because:", o:["Ram effect ceases to function in the isothermal layer","Engine RPM must be reduced to protect the turbine","Temperature stabilizes and no longer offsets the density decrease caused by falling pressure","Fuel flow must be increased to maintain the same EPR"], a:2, r:"Below the isothermal layer, falling temperature partially offsets the density loss from falling pressure. Once temperature stabilizes (~36,000 ft), that offset disappears and thrust decays faster.", ref:"Ch 1, EO 2.67"},
    {q:"Considering only the thrust equation and IGNORING ram effect, an increase in airspeed reduces thrust because:", o:["Mass airflow through the engine decreases","The difference between exhaust velocity and inlet velocity decreases","Exhaust velocity is reduced by inlet compression","Air density at the inlet falls with dynamic pressure"], a:1, r:"Net Thrust = m × (V final − V initial)/t. As inlet velocity approaches exhaust velocity, the acceleration term shrinks. This thrust decrease is theoretical — ram effect offsets it in practice.", ref:"Ch 1, EO 2.67/2.68"},
    {q:"Gas turbine engines are normally operated near their maximum RPM because:", o:["The turbine section is only stressed at low RPM","At low RPM, fuel consumption is high for the amount of thrust produced, while at high RPM a small throttle increase produces a large thrust increase","The FCU cannot meter fuel accurately below 80% RPM","Compressor stall margin is lowest at high RPM"], a:1, r:"At low RPM there is very little thrust increase per unit of throttle and fuel consumption is high for the thrust produced; at high RPM a small throttle increase yields a large thrust increase.", ref:"Ch 1, EO 2.67"},
    {q:"Which of the following instruments does NOT actually measure thrust, yet is the gauge most commonly used by a pilot to determine engine performance?", o:["EPR gauge","Torquemeter","Tachometer","ITT gauge"], a:2, r:"The tachometer indicates engine speed in percent RPM. It does not measure thrust, but it is the gauge most commonly used to assess engine performance.", ref:"Ch 1, EO 2.69"},
    {q:"Airflow passes through a subsonic diffuser. Which statement is correct?", o:["Static pressure increases, dynamic pressure decreases, and total pressure remains the same","Static pressure increases, dynamic pressure increases, and total pressure increases","Static pressure decreases, dynamic pressure increases, and total pressure remains the same","Static pressure increases, dynamic pressure decreases, and total pressure decreases"], a:0, r:"A diffuser converts dynamic pressure into static pressure. In a closed system total pressure is unchanged — only the split between static and dynamic shifts. (Contrast with the compressor, which is not closed and does raise total pressure.)", ref:"Ch 1, EO 2.11/2.62"},
    {q:"On an unusually hot day, an engine's thrust may vary from its standard rated thrust by as much as:", o:["5 percent","10 percent","20 percent","50 percent"], a:2, r:"Thrust may vary as much as 20 percent from standard rated thrust on a hot or cold day.", ref:"Ch 1, EO 2.67"},
    {q:"Which of the following is NOT a reason the high pressure spool turns faster than the low pressure spool?", o:["The HP spool is smaller and lighter in weight","Higher air temperature after compression raises the local speed of sound","The HP compressor blades are shorter and can turn faster before exceeding their limiting Mach number","The HP compressor is driven by the low pressure turbine, which receives more energy"], a:3, r:"The HP compressor is driven by the HIGH pressure turbine, located forward of the LP turbine and therefore receiving more energy. The other three are all valid reasons.", ref:"Ch 2, EO 2.71"},
    {q:"On a dual-spool axial flow engine, the engine starter is connected to, and the fuel control governs the speed of, the:", o:["Front (low pressure) compressor rotor","Rear (high pressure) compressor rotor","Low pressure turbine shaft","Accessory gear box output shaft"], a:1, r:"“Usually, the rear compressor rotor is speed-governed by the engine fuel control and is the rotor to which the engine starter is connected.”", ref:"Ch 2, EO 2.71"},
    {q:"Typical compression ratios are approximately ______ for a centrifugal compressor and approach ______ for a current axial compressor.", o:["15:1; 6:1 to 7:1","6:1 to 7:1; 15:1","2:1; 25:1","6:1 to 7:1; 90:1"], a:1, r:"Centrifugal: 6:1 to 7:1. Current axial: efficiency near 90% with ratios approaching 15:1, and near 25:1 on several high performance engines.", ref:"Ch 2, EO 2.71"},
    {q:"Which of the following is NOT one of the design criteria for the burner section?", o:["Pressure decrease through the burner must be minimized","Combustion efficiency must remain high","Airflow velocity must be increased before the flame front","All burning must be complete before the gases enter the turbine section"], a:2, r:"Velocity must DECREASE slightly at the diffuser to avoid blowing out the flame. The four criteria are minimum pressure loss, high combustion efficiency, flame must not blow out, and complete burning before the turbine.", ref:"Ch 2, EO 2.72"},
    {q:"The exact amount of energy absorbed by the turbine section is determined by:", o:["Turbine inlet temperature alone","The load the turbine is driving — compressor size, compressor type, and accessories","The position of the variable exhaust nozzle","The bypass ratio of the engine"], a:1, r:"Approximately 75% of total pressure energy is converted, but the exact amount absorbed depends on the load: compressor size, compressor type, and accessories.", ref:"Ch 2, EO 2.74"},
    {q:"Which pairing is correct?", o:["Creep is the attachment method that permits blade expansion; fir tree is blade elongation from heat","Creep is elongation of turbine blades from heat; fir tree is the attachment method permitting expansion","Both creep and fir tree describe compressor blade attachment methods","Creep is elongation of compressor blades from cold soak; fir tree prevents FOD"], a:1, r:"Creep = cumulative elongation/deformation of turbine blades from heat. Fir tree = the attachment method that lets blades expand when heated, preventing cracking at the attachment points.", ref:"Ch 2, EO 2.74/2.75"},
    {q:"Gases in a convergent exhaust nozzle cannot exceed the speed of sound because:", o:["The turbine has already extracted all available kinetic energy","As gas velocity increases, the ability of the pressure behind it to push the molecules decreases","The nozzle area is fixed on all subsonic aircraft","Secondary air cools the gases below the critical temperature"], a:1, r:"Each subsonic gas molecule is pushed from behind. As velocity rises, pressure's ability to keep pushing diminishes, so the flow chokes at sonic. Going supersonic requires the divergent section of a C-D nozzle.", ref:"Ch 2, EO 2.76"},
    {q:"Afterburning increases maximum available thrust by ______ or more, at a fuel consumption increase of approximately ______. On a TURBOJET, the air used for afterburner combustion is ______.", o:["50%; 300%; secondary air from the burner section","300%; 50%; bypass air only","50%; 300%; primary air from the burner section","25%; 100%; interstage bleed air"], a:0, r:"50%+ thrust increase for roughly 300% more fuel. On a turbojet, secondary air from the burner section feeds afterburner combustion; on a turbofan, secondary air plus bypass air.", ref:"Ch 2, EO 2.77"},
    {q:"Screech is best described as, and controlled by:", o:["A back pressure condition caused by a failed variable nozzle; controlled by opening the nozzle","Violent pressure fluctuations from cyclic vibrations; controlled by corrugated, perforated inner sleeves acting as a shock absorber","An unstable shock wave in the inlet duct; controlled by variable geometry ramps","Blade flutter in the low pressure turbine; controlled by fir tree attachment"], a:1, r:"Screech is violent pressure fluctuation from cyclic vibration, characterized by loud noise and vibration; screech liners are corrugated, perforated sleeves acting as shock absorbers.", ref:"Ch 2, EO 2.77"},
    {q:"Variable inlet guide vanes and variable stator vanes are automatically positioned by the ______ using ______.", o:["Fuel control unit; bleed air pressure","Stator vane actuator; fuel pressure supplied via the fuel control unit","Power control lever; a direct mechanical linkage","Bleed valve actuator; hydraulic system pressure"], a:1, r:"The stator vane actuator (SVA) positions them, using fuel pressure supplied via the FCU. Note the trap: the FCU is upstream in the chain, but the SVA is the component that does the positioning.", ref:"Ch 3, EO 3.15"},
    {q:"Bleed valves are installed near the middle or rear of the compressor in order to:", o:["Supply high pressure air for engine and inlet anti-ice","Vent air to the atmosphere and increase airflow in the front of the compressor at low engine RPM","Reduce turbine inlet temperature during afterburner operation","Provide a constant volume of air to the accessory drive gearbox"], a:1, r:"Bleed valves vent air to the atmosphere near the middle or rear of the compressor, increasing airflow at the front of the compressor at low engine RPM — reducing blade AOA and stall potential.", ref:"Ch 3, EO 3.15"},
    {q:"A variable exhaust nozzle that FAILS TO OPEN during afterburner operation causes a compressor stall by:", o:["Reducing the mass of secondary air available for combustion","Producing excessive back pressure and reverse flow back through the compressor","Increasing compressor RPM beyond its limiting Mach number","Causing the FCU to schedule an over-lean mixture"], a:1, r:"A nozzle that fails to open traps exhaust gases, creating excessive back pressure and reverse flow back through the compressor.", ref:"Ch 3, EO 3.13"},
    {q:"Which of the following, occurring by itself, will INCREASE compressor blade angle of attack?", o:["An increase in inlet airflow velocity","A decrease in compressor RPM","A decrease in inlet airflow velocity","An increase in ambient pressure at constant RPM"], a:2, r:"AOA rises when relative wind shifts — anything that decreases inlet airflow or increases compressor RPM increases AOA and stall potential.", ref:"Ch 3, EO 3.11"},
    {q:"In a turbofan, the gas generator turbine extracts ______ of the total energy leaving the burner section. Of the remainder, ______.", o:["25%; part drives the fan and part exits as kinetic energy","75%; part is converted to mechanical energy to drive the fan and the rest exits the exhaust as kinetic energy","75%; all of it exits the exhaust as kinetic energy","40–70%; part drives the fan and part drives the accessories"], a:1, r:"The gas generator turbine takes 75% just to drive the compressor and accessories. The remaining 25% splits: part converted to mechanical energy through the turbines to drive the fan, part exiting as exhaust kinetic energy.", ref:"Ch 4, EO 2.81/2.82"},
    {q:"A high bypass turbofan is limited at high airspeed and high altitude because:", o:["The fan cannot be driven above 100% RPM and the compressor chokes","A large mass of air is accelerated to only moderate speeds, and at altitude lower density means a smaller mass is accelerated by the fan","The bypass duct produces sonic shock waves that damage the fan","TSFC rises sharply above 36,000 feet"], a:1, r:"High-end airspeed is limited because a large air mass is accelerated to only moderate speeds; altitude is limited because lower density means a smaller mass is accelerated by the fan.", ref:"Ch 4, EO 2.87"},
    {q:"In the T-6B, the reduction gear box reduces power turbine output shaft speed from over ______ to a propeller operating speed of ______.", o:["15,000 RPM; 1,000 RPM","30,000 RPM; 2,000 RPM","10,000 RPM; 2,000 RPM","30,000 RPM; 100 RPM"], a:1, r:"T-6B NATOPS: a two-stage planetary reduction drive reduces power turbine output shaft speed of over 30,000 RPM to a propeller speed of 2,000 RPM.", ref:"Ch 4, EO 2.89"},
    {q:"In turboprop alpha-range operation, the ______ determines the blade angle required to hold constant propeller RPM, while the ______ is the mechanism that physically changes the blade angle.", o:["Fuel control unit; reduction gear box","Propeller governor; pitch change/dome assembly","Torquemeter assembly; hub assembly","Power control lever; propeller governor"], a:1, r:"The propeller governor is the “brain” of the propeller assembly and works with the FCU to hold constant RPM; the pitch change/dome assembly is the mechanism that actually changes blade angle. Naming the FCU or the PCL here is the classic near-miss.", ref:"Ch 4, EO 2.88/2.91"},
    {q:"A pilot increases fuel flow in a turboprop during flight. The correct sequence is:", o:["Propeller RPM increases, then blade angle decreases to compensate","Turbine temperature rises, more energy is absorbed and sent to the propeller as torque, and blade angle increases to maintain constant RPM","Blade angle decreases first, allowing propeller RPM to rise to a new steady state","The RGB ratio changes to convert the additional torque into propeller RPM"], a:1, r:"Increased fuel flow → higher turbine temperature → more energy available → turbine absorbs more and sends it to the propeller as torque → propeller increases blade angle to absorb the torque and maintain constant RPM.", ref:"Ch 4, EO 2.91"},
    {q:"Ranked from HIGHEST TSFC to LOWEST TSFC, the correct order is:", o:["Turboprop, turbofan, turbojet","Turbofan, turbojet, turboprop","Turbojet, turbofan, turboprop","Turbojet, turboprop, turbofan"], a:2, r:"Turbojet has the highest TSFC; turbofan is better; turboprop is lowest because it accelerates a large mass of air at low velocity for relatively little fuel.", ref:"Ch 4, EO 2.84/2.85"},
    {q:"Up to medium airspeeds, the engine that delivers the most thrust — and its practical speed limitation — is the:", o:["Turbojet; unlimited","Turbofan; 450 knots","Turboprop; approximately 450 knots","Turboshaft; 250 knots"], a:2, r:"The turboprop delivers more thrust than the turbojet or turbofan up to medium speeds, but is limited to approximately 450 knots.", ref:"Ch 4, EO 2.88"},
    {q:"In a reciprocating engine, the propeller may be driven ______ and the ______ controls blade angle and propeller speed.", o:["Only through a reduction gear box; pitch change dome","Directly by the crankshaft or through a reduction gear box; governor","Directly by the camshaft or through a torque shaft; FCU","Only directly by the crankshaft; magneto"], a:1, r:"Propellers are driven directly by the crankshaft (direct drive) or through a reduction gear box; a governor controls blade angle and propeller speed.", ref:"Ch 4, EO 2.78"},
    {q:"A hydraulic system multiplies an input force tenfold. If the input piston travels 1 inch, the output piston will travel:", o:["10 inches","1 inch","1/10 inch","100 inches"], a:2, r:"Force multiplication is bought with linear displacement, and the two are inversely proportional. Ten times the force means one tenth the travel: 1/10 inch.", ref:"Ch 5, EO 2.95"},
    {q:"The difference between a pressure regulator and an unloader valve is that the pressure regulator ______ while the unloader valve ______.", o:["Diverts all pump flow back to the reservoir at a preset pressure; diverts only excess flow","Diverts excess pump flow back to the reservoir to maintain a set pressure; diverts all pump flow back to the reservoir once preset pressure is reached","Limits maximum system pressure to prevent seal rupture; isolates a leaking subsystem","Directs fluid to the actuator working port; returns fluid to the reservoir"], a:1, r:"The pressure regulator maintains a set pressure by diverting EXCESS flow back to the reservoir; the unloader valve diverts ALL pump flow back to the reservoir once preset pressure is reached, until further demand exists.", ref:"Ch 5, EO 2.96"},
    {q:"A pressurized hydraulic reservoir on a high performance aircraft is normally pressurized during normal operation by:", o:["Nitrogen from a precharged bottle","Engine bleed air","The accumulator's air chamber","Ram air from the inlet duct"], a:1, r:"“During normal operation, the pressurizing air source comes from engine bleed air.” Reservoirs may alternatively be pressurized by hydraulic system pressure, but bleed air is the normal source.", ref:"Ch 5, EO 2.96"},
    {q:"A hydraulic line is severed during combat. The component specifically designed to prevent excessive loss of fluid while allowing the remaining subsystems to operate is the:", o:["Relief valve","Check valve","Hydraulic fuse","Pressure switch"], a:2, r:"Hydraulic fuses detect ruptures, failed fittings, and other leak-producing failures, preventing excessive fluid loss while permitting the remaining subsystems to operate.", ref:"Ch 5, EO 2.96"},
    {q:"A generator requires a constant rotational input speed regardless of engine RPM. The component that provides this is the ______, and the section the generator is mechanically coupled to is the ______.", o:["Accessory drive section; constant speed drive","Constant speed drive; accessory drive section","Transformer rectifier; high pressure compressor spool","Inverter; accessory drive section"], a:1, r:"The CSD provides the constant input RPM; the generator is mechanically coupled to the engine's accessory drive section, whose RPM is rarely constant. Naming the accessory drive section as the regulating device is the trap.", ref:"Ch 6, EO 2.98"},
    {q:"An APU is best described as:", o:["An electrically driven pump that pressurizes the utility hydraulic system","A small, independent gas turbine engine that drives a backup generator through a driveshaft and gearbox","A ground support cart supplying regulated AC and DC power","A battery pack sized to start one engine"], a:1, r:"The APU is a small, independent gas turbine that provides power through a driveshaft to a gearbox turning a backup generator, freeing the aircraft from external power. (c) describes ground support equipment.", ref:"Ch 6, EO 2.98"},
    {q:"Which bus charges the aircraft battery?", o:["The AC essential bus","The DC essential bus","The starter bus","The monitor bus"], a:1, r:"The DC essential bus charges the battery.", ref:"Ch 6, EO 2.98"},
    {q:"A radar set, a primary attitude gyro, and cabin lighting are powered respectively by the:", o:["Essential, primary, and monitor buses","Primary, essential, and monitor buses","Monitor, primary, and essential buses","Primary, monitor, and essential buses"], a:1, r:"Radar = mission = primary bus. Primary attitude gyro = flight safety = essential bus. Cabin lighting = convenience = monitor/secondary bus.", ref:"Ch 6, EO 2.98"},
    {q:"Rank the following by flash point, LOWEST to HIGHEST:", o:["Avgas, JP-4, JP-8, JP-5","JP-4, Avgas, JP-5, JP-8","JP-5, JP-8, JP-4, Avgas","Avgas, JP-8, JP-4, JP-5"], a:0, r:"Avgas −45 °F, JP-4 −35 °F, JP-8 100 °F, JP-5 140 °F.", ref:"Ch 7, EO 2.100/2.102"},
    {q:"During an engine start, the dump valve within the P&D valve is held closed by ______, and it is subsequently held closed by ______ until shutdown.", o:["Spring pressure; an electrical signal from the FCU","An electrical (pressure) signal from the FCU; fuel flow pressure","Boost pump pressure; the pressurizing valve","Manifold back pressure; spring pressure"], a:1, r:"At start, the dump valve is closed by an electrical (pressure) signal from the FCU; thereafter fuel flow pressure holds it closed until shutdown, when falling pressure lets the spring open it to drain the manifolds.", ref:"Ch 7, EO 2.103"},
    {q:"The PRIMARY fuel manifold has smaller diameter tubes than the secondary manifold in order to:", o:["Reduce the total weight of the manifold assembly","Allow fuel to reach comparatively high pressure and atomization during starting and altitude idling","Limit the maximum fuel flow available at military rated thrust","Prevent water in the fuel from reaching the nozzles"], a:1, r:"Smaller primary tubes let fuel reach comparatively high pressure and atomization during starting and altitude idling. The secondary manifold takes over once RPM raises fuel pressure past a predetermined level.", ref:"Ch 7, EO 2.103"},
    {q:"In manual/emergency fuel control, the system:", o:["Retains RPM governing but loses acceleration limiting","Bypasses the FCU and loses both acceleration-limiting and RPM-governing capability, with the PCL functioning as a throttle","Cannot be used for engine starting or afterburning","Automatically adjusts fuel flow using CIT and ITT only"], a:1, r:"Manual/emergency bypasses the FCU. It is simpler but lacks acceleration limiting and RPM governing; the PCL functions as a throttle, and it may be used for starting and afterburning with close cockpit attention.", ref:"Ch 7, EO 2.103"},
    {q:"Which component CUTS OFF fuel flow at engine shutdown, and which component DRAINS the combustion manifolds after shutdown?", o:["The P&D valve cuts off fuel flow; the FCU drains the manifolds","The FCU cuts off fuel flow; the P&D valve drains the manifolds","The emergency shutoff handle cuts off fuel flow; the fuel transfer valve drains the manifolds","The boost pump cuts off fuel flow; the low pressure filter bypass drains the manifolds"], a:1, r:"The FCU cuts off fuel flow at shutdown; the P&D valve drains the combustion manifolds so residual fuel doesn't cause an engine fire, a hot start, or carbon/gum deposits. Some older gouge answers this incorrectly — the SG is explicit.", ref:"Ch 7, EO 2.103"},
    {q:"The oil temperature gauge displays oil temperature ______ and is used to indicate the performance of the ______ subsystem.", o:["At the pressure pump discharge; pressure","Prior to entering the engine bearing compartments; scavenge","After leaving the bearing compartments; breather pressurizing","At the oil tank outlet; pressure"], a:1, r:"The oil temperature gauge reads oil temperature prior to entering the bearing compartments, and it indicates the performance of the scavenge subsystem, which contains the oil coolers.", ref:"Ch 8, EO 2.108"},
    {q:"The oil temperature regulating valve is located ______ and, when no oil cooling is required, it ______.", o:["In the fuel outlet line of the heat exchanger; opens the air-oil cooler doors","At the oil entrance to the fuel-oil heat exchanger; remains closed and routes oil directly to the oil tank","At the scavenge pump inlet; returns oil to the pump inlet","At the oil entrance to the fuel-oil heat exchanger; opens fully to maximize cooling"], a:1, r:"It sits at the oil entrance to the fuel-oil heat exchanger. If no cooling is needed it stays closed, routing oil straight to the tank and bypassing the exchanger. (a) is the fuel temperature sensing switch.", ref:"Ch 8, EO 2.108"},
    {q:"As an aircraft climbs, the breather pressurizing valve:", o:["Opens progressively to vent increasing sump pressure overboard","Closes gradually to maintain approximately 29.92 in-Hg within the oil tank and bearing compartments","Remains fully open, with the aneroid bellows serving only as a relief device","Closes fully at 36,000 feet and reopens on descent"], a:1, r:"The valve is open to atmosphere at sea level and closes gradually with increasing altitude to maintain approximately 29.92 in-Hg. The spring-loaded blow-off valve is a separate relief function.", ref:"Ch 8, EO 2.108"},
    {q:"MIL-L-7808 and MIL-L-23699 are mixed in an engine. The result is:", o:["A thick, sticky mass with poor lubricating qualities","An acceptable mixture, with the characteristics of 23699 downgraded to those of 7808","An acceptable mixture, with the characteristics of 7808 upgraded to those of 23699","Immediate coking of the bearing compartments"], a:1, r:"7808 and 23699 are both synthetics and may be safely mixed when necessary, but 23699 is downgraded to 7808 qualities. (a) describes mixing synthetic with mineral/petroleum oil — never permitted.", ref:"Ch 8, EO 2.106"},
    {q:"Compressor discharge air used to drive accessories is bled ______, and typically amounts to ______ of the total airflow through the engine.", o:["At the compressor face only; 10 to 15 percent","Through ports or valves along the compressor case and at the end of the diffuser; 1 to 4 percent","From the exhaust cone struts; 1 to 4 percent","Between the turbine stages; 10 to 15 percent"], a:1, r:"Compressor discharge air is bled through ports or valves at intervals along the compressor case and at the end of the diffuser; 1 to 4 percent of total airflow is available for driving accessories.", ref:"Ch 9, EO 2.109/2.111"},
    {q:"Dual-axial compressor engines usually have:", o:["One accessory drive gear box, connected to the high pressure compressor","Two accessory drive gear boxes, one connected to the low pressure compressor and one to the high pressure compressor","Three accessory drive gear boxes, one per bleed air system","No accessory drive gear box; all accessories are bleed air driven"], a:1, r:"Two accessory drive gear boxes: one connected to the low pressure compressor, one to the high pressure compressor.", ref:"Ch 9, EO 2.110"},
    {q:"The type of ignitor plug whose spark JUMPS IN AN ARC BEYOND the face of the chamber liner — and therefore runs cooler — is the:", o:["Annular-gap plug","Constrained-gap plug","High heat-intensity capacitor plug","Constrained-annular plug"], a:1, r:"The constrained-gap plug's spark does not closely follow the face of the plug; it arcs beyond the face of the chamber liner and consequently runs cooler. The annular-gap plug protrudes slightly into the liner. Some review sheets key this incorrectly as annular gap — the Student Guide is unambiguous.", ref:"Ch 9, EO 5.5"},
    {q:"Which statement about abnormal starts is correct?", o:["A hot start is an ignition problem and is the most dangerous abnormal start","A wet start is an ignition problem and is the most dangerous abnormal start","A hung start is defined as exceeding the maximum allowable turbine temperature during start","A false start occurs when turbine temperature continues to rise while RPM stabilizes below normal"], a:1, r:"Wet start = fuel-air mixture does not light off initially but retains the capability to ignite; it is an ignition problem and the most dangerous abnormal start. Hot start = exceeding max turbine temperature. Hung start = rising temperature with RPM below normal. False start = RPM below normal with temperature within limits.", ref:"Ch 9, EO 5.2"}
  ]
},
{
  name: "Chapters 1\u20133 \u2014 Principles, Sections & Stalls",
  desc: "Chapter-focused review: Principles of Operation, Engine Sections, and Compressor Stalls.",
  questions: [
    {q:"In a closed system, total pressure is the sum of:", o:["Static pressure and ambient pressure", "Static pressure and dynamic pressure", "Dynamic pressure and ram pressure", "Ram pressure and velocity"], a:1, r:"Total Pressure = Static Pressure + Dynamic Pressure (pressure + velocity).", ref:"Ch 1, EO 2.11"},
    {q:"Subsonic airflow passing through a convergent opening will experience:", o:["An increase in velocity and an increase in pressure", "A decrease in velocity and an increase in pressure", "An increase in velocity and a decrease in pressure", "A decrease in velocity and a decrease in pressure"], a:2, r:"Bernoulli's Theorem: subsonic flow through a convergent opening increases velocity and decreases pressure.", ref:"Ch 1, EO 2.61"},
    {q:"Supersonic airflow passing through a divergent opening will experience:", o:["An increase in velocity and a decrease in pressure", "A decrease in velocity and an increase in pressure", "An increase in both velocity and pressure", "No change, since supersonic flow is incompressible"], a:0, r:"Supersonic flow acts opposite to Bernoulli. Divergent = velocity increases, pressure decreases.", ref:"Ch 1, EO 2.61"},
    {q:"A supersonic diffuser is _______ in shape, and a subsonic nozzle is _______ in shape.", o:["Divergent / divergent", "Convergent / divergent", "Convergent / convergent", "Divergent / convergent"], a:2, r:"A diffuser increases pressure/decreases velocity; supersonic requires convergent. A nozzle increases velocity/decreases pressure; subsonic requires convergent. Trap: the shape flips with the flow regime, not with the device name \u2014 build the 2\u00d72 table (nozzle/diffuser \u00d7 sub/supersonic) rather than memorizing shapes alone.", ref:"Ch 1, EO 2.61/2.62"},
    {q:"The three sections common to every gas generator are the:", o:["Inlet, compressor, and turbine", "Compressor, combustion chamber, and turbine", "Compressor, turbine, and exhaust", "Inlet, burner, and exhaust nozzle"], a:1, r:"All gas turbine engines contain at minimum a compressor, combustion chamber, and turbine. The inlet and exhaust are added to the gas generator to make a turbojet (Ch 4), so A, C, and D each substitute an add-on section for a core section.", ref:"Ch 1, EO 2.64"},
    {q:"The four events of the Brayton cycle occur:", o:["Sequentially, within a single piston", "Sequentially, throughout the gas turbine engine", "Simultaneously, within a single piston", "Simultaneously, throughout the gas turbine engine"], a:3, r:"Brayton events (intake, compression, combustion, exhaust) occur simultaneously and throughout the engine. Sequential/single-piston describes the Otto cycle.", ref:"Ch 1, EO 2.63"},
    {q:"Gross thrust is measured under what conditions?", o:["Normal flight conditions at cruise altitude", "Standard day (29.92\" Hg and 15 \u00b0C) with inlet velocity ignored", "Standard day, with inlet airflow velocity corrected for", "Maximum continuous turbine temperature"], a:1, r:"Gross thrust is measured at standard day (29.92\" Hg, 15 \u00b0C) and ignores inlet airflow velocity. C describes net thrust.", ref:"Ch 1, EO 2.66"},
    {q:"Gross thrust and net thrust are equal when:", o:["The aircraft is at 36,000 feet", "The engine is at military rated thrust", "The aircraft is static and standard day conditions exist", "Ram effect equals inlet drag"], a:2, r:"Net thrust equals gross thrust when inlet velocity is zero (static) and conditions are standard.", ref:"Ch 1, EO 2.66"},
    {q:"Thrust may vary as much as _____ percent from standard rated thrust on a hot or cold day.", o:["10", "20", "30", "50"], a:1, r:"20 percent.", ref:"Ch 1, EO 2.67"},
    {q:"As an aircraft climbs, thrust decreases because:", o:["The temperature drop is greater than the pressure drop", "The pressure drop is greater than the thrust increase from the temperature drop", "Ram effect is lost above 20,000 feet", "RPM must be reduced with altitude"], a:1, r:"Both pressure and temperature drop with altitude, but the thrust loss from the pressure drop exceeds the thrust gain from the temperature drop.", ref:"Ch 1, EO 2.67"},
    {q:"Approximately 36,000 feet is referred to as the optimum cruise level because:", o:["Ram effect is at its maximum", "Temperature stabilizes, and thrust available plus low fuel flow and reduced drag combine for optimum performance", "Air density is at its highest usable value", "The engine reaches 100% RPM at this altitude"], a:1, r:"At the start of the isothermal layer, temperature stabilizes and no longer offsets the density decrease; thrust available plus low fuel flow and diminished drag give optimum performance.", ref:"Ch 1, EO 2.67"},
    {q:"Considering airspeed and ram effect together, thrust at supersonic airspeeds will:", o:["Decrease significantly", "Remain relatively constant", "Increase significantly", "Decrease, then stabilize"], a:2, r:"Ram effect produces a significant increase in overall thrust at supersonic speeds. At subsonic speeds ram effect produces a neutral effect or slight increase \u2014 that's answer B's scenario.", ref:"Ch 1, EO 2.68"},
    {q:"Which cockpit instrument indicates the pressure ratio between inlet and exhaust airflow?", o:["Tachometer", "Torquemeter", "EPR gauge", "ITT gauge"], a:2, r:"The EPR gauge indicates the pressure ratio between inlet and exhaust airflow, used on turbojets and turbofans.", ref:"Ch 1, EO 2.69"},
    {q:"An inlet duct is designed to act as a:", o:["Nozzle at all airspeeds", "Diffuser, but never a nozzle", "Nozzle at subsonic speeds and a diffuser at supersonic speeds", "Diffuser at subsonic speeds and a nozzle at supersonic speeds"], a:1, r:"Inlet ducts are normally designed to act as a diffuser but never as a nozzle, in every flight regime.", ref:"Ch 2, EO 2.70"},
    {q:"The rapid swallowing and expelling of a shock wave at the mouth of a supersonic inlet duct is known as:", o:["Screech", "Creep", "Inlet buzz", "Choking"], a:2, r:"Inlet buzz is an airflow instability caused by the shock wave rapidly being swallowed and expelled at the duct inlet. Screech (A) is an afterburner phenomenon; creep (B) is turbine blade deformation.", ref:"Ch 2, EO 2.70"},
    {q:"The three main components of a centrifugal flow compressor are the:", o:["Rotor, stator, and diffuser", "Impeller, diffuser, and manifold", "Impeller, rotor, and manifold", "Inducer, stator, and burner basket"], a:1, r:"Impeller (rotor inducer), diffuser, and manifold.", ref:"Ch 2, EO 2.71"},
    {q:"Which component of the centrifugal compressor increases velocity, pressure, AND total pressure?", o:["Impeller", "Diffuser", "Manifold", "Exit guide vanes"], a:0, r:"The impeller increases velocity (rotation) and pressure (divergent passages), so total pressure increases. The diffuser converts velocity to pressure with total pressure constant; the manifold merely routes air to the burner.", ref:"Ch 2, EO 2.71"},
    {q:"A typical centrifugal flow compressor attains a compression ratio of approximately:", o:["1:1 to 2:1", "6:1 to 7:1", "12:1 to 15:1", "25:1"], a:1, r:"6:1 to 7:1 for centrifugal; axial designs approach 15:1 with high-performance engines near 25:1.", ref:"Ch 2, EO 2.71"},
    {q:"In an axial flow compressor, one rotor and one stator together form a:", o:["Spool", "Stage", "Case", "Section"], a:1, r:"Each rotor and stator pair forms a stage.", ref:"Ch 2, EO 2.71"},
    {q:"Inlet guide vanes improve compressor performance by:", o:["Straightening the airflow prior to the diffuser", "Imparting a swirling motion in the direction of engine rotation to reduce drag on the first-stage rotor blades", "Bleeding excess air overboard at low RPM", "Converting velocity into pressure prior to combustion"], a:1, r:"Inlet guide vanes impart swirl in the direction of engine rotation, reducing drag on the first-stage rotor blades. A describes exit (straightening) guide vanes.", ref:"Ch 2, EO 2.71"},
    {q:"The function of the diffuser (located after the compressor) is to:", o:["Increase velocity and decrease pressure before the burner", "Provide a final decrease in velocity and increase in pressure prior to combustion", "Straighten the airflow coming off the compressor rotors", "Divide the airflow into primary and secondary air"], a:1, r:"The diffuser gives the airflow a final velocity decrease and pressure increase; velocity must drop slightly to avoid blowing out the burner flame.", ref:"Ch 2, EO 2.71"},
    {q:"Of the airflow entering the burner section, secondary air accounts for _____ percent and is used for:", o:["25 / combustion", "25 / cooling and flame control", "75 / combustion", "75 / cooling and flame control"], a:3, r:"Secondary air is 75 percent, used to cool the thin walls and control the flame. Primary air is 25 percent and mixes with fuel for combustion. Note the naming conflict: \"primary/secondary air\" (25/75, burner) is a completely separate system from \"primary/secondary manifold\" (fuel, Ch 7). Keep two separate mental maps.", ref:"Ch 2, EO 2.72"},
    {q:"Which combustion chamber offers ease of maintenance but may produce cold spots and uneven heat distribution at the turbine inlet?", o:["Can", "Annular", "Can-annular", "Cannular-radial"], a:0, r:"The can type is easy to maintain but has poor space use, greater pressure loss, and uneven heat distribution; a single can malfunction can damage the turbine.", ref:"Ch 2, EO 2.73"},
    {q:"Approximately what percentage of the total energy from the exhaust gases is extracted by the turbine to drive the compressor and accessories?", o:["25 percent", "40 percent", "60 percent", "75 percent"], a:3, r:"Approximately 75 percent of the total pressure energy is converted by the turbine rotor; the remaining 25 percent is used for thrust. Trap: don't transpose this with the burner air split (25% primary / 75% secondary). Memory hook: air is 25 primary; energy is 75 to the turbine.", ref:"Ch 2, EO 2.74"},
    {q:"Turbine blade elongation and deformation caused by heat over time is known as:", o:["Creep", "Screech", "Coking", "Fir tree"], a:0, r:"Creep is blade elongation/deformation, a cumulative process. Fir tree (D) is the blade attachment method that mitigates thermal stress.", ref:"Ch 2, EO 2.75"},
    {q:"The four parts of the afterburner discussed in the Student Guide are the:", o:["Spray bars, fuel nozzles, screech liner, and fixed exhaust nozzle", "Spray bars, flame holder, screech liner, and variable exhaust nozzle", "Fuel manifold, flame holder, inner cone, and variable exhaust nozzle", "Spray bars, flame holder, exhaust cone, and radial struts"], a:1, r:"Spray bars, flame holders, screech liner, variable exhaust nozzle.", ref:"Ch 2, EO 2.77"},
    {q:"The angle of attack of a compressor rotor blade is the angle between the blade's chord line and the relative wind, which is formed by:", o:["Inlet airflow and compressor RPM", "Inlet airflow and turbine RPM", "Compressor RPM and exhaust velocity", "Aircraft angle of attack and compressor RPM"], a:0, r:"The relative wind within the compressor is formed by combining compressor rotation (RPM) and the inlet airflow.", ref:"Ch 3, EO 3.11"},
    {q:"Which of the following is the most common cause of a compressor stall?", o:["Fuel control unit failure", "Foreign object damage", "Airflow distortion", "Variable exhaust nozzle failure"], a:2, r:"Airflow distortion is the most common cause. The four mechanical malfunctions (VIGV/stator vanes, FCU, FOD, variable exhaust nozzle) are the other main category.", ref:"Ch 3, EO 3.12"},
    {q:"With the PCL held in a constant position, indications of a compressor stall include:", o:["RPM increase and ITT decrease", "RPM decay and ITT rise, with possible loud noises", "RPM increase and ITT rise, with fluctuating fuel flow", "RPM decay and ITT decrease, with mild pulsations"], a:1, r:"A stall reduces airflow to the turbines, so more fuel is required to hold thrust, raising burner and turbine temperature while RPM decays.", ref:"Ch 3, EO 3.12"},
    {q:"To reduce the possibility of a compressor stall, bleed valves are installed:", o:["At the face of the compressor", "Near the middle or rear of the compressor", "At the exit of the diffuser only", "Downstream of the turbine section"], a:1, r:"Bleed valves are installed near the middle or rear of the compressor to vent air and increase airflow at the front of the compressor at low engine RPM. High-frequency miss: the valves sit mid/aft, but their purpose is to unload the front stages \u2014 don't let the effect location pull you to answer A.", ref:"Ch 3, EO 3.15"},
  ]
},
{
  name: "Chapters 4\u20136 \u2014 Engine Types, Hydraulics & Electrical",
  desc: "Chapter-focused review: Engine Types, Hydraulic Systems, and Electrical Systems.",
  questions: [
    {q:"Thrust Specific Fuel Consumption (TSFC) is defined as:", o:["The total fuel burned per hour of operation", "The amount of fuel required to produce one pound of thrust", "The ratio of fuel flow to compressor RPM", "The amount of thrust produced per gallon of fuel"], a:1, r:"TSFC is the amount of fuel required to produce one pound of thrust.", ref:"Ch 4, EO 2.83"},
    {q:"A turbojet produces thrust by:", o:["Accelerating a large mass of air to a moderate velocity", "Greatly accelerating a small mass of air", "Bypassing a large mass of air around the gas generator", "Converting nearly all pressure energy into shaft horsepower"], a:1, r:"The turbojet derives thrust by highly accelerating a small mass of air; all inlet air traverses the gas generator. A describes the turboprop; C the turbofan; D the turboshaft.", ref:"Ch 4, EO 2.79"},
    {q:"Which of the following is a characteristic of the turbojet engine?", o:["Lowest TSFC and shortest takeoff roll", "Highest TSFC and longest takeoff roll", "Lowest TSFC and longest takeoff roll", "Highest TSFC and shortest takeoff roll"], a:1, r:"Turbojet: best high-speed/high-altitude performance, highest TSFC, longest takeoff rolls.", ref:"Ch 4, EO 2.80"},
    {q:"One hundred percent propulsive efficiency would theoretically be reached when:", o:["The engine is operating at 100% RPM", "Bypass ratio reaches 6:1", "The aircraft's speed equals the exhaust velocity", "Inlet velocity equals zero"], a:2, r:"If the aircraft's speed equaled exhaust velocity, one hundred percent propulsive efficiency would be reached.", ref:"Ch 4, EO 2.86"},
    {q:"In a turbofan engine, the fan produces _____ percent of total thrust and the gas generator exhaust produces _____ percent.", o:["10 / 90", "25 / 75", "30\u201360 / 40\u201370", "40\u201370 / 30\u201360"], a:2, r:"Fan: 30\u201360 percent. Gas generator exhaust: 40\u201370 percent. Answer D reverses them \u2014 a common transposition.", ref:"Ch 4, EO 2.81"},
    {q:"A bypass ratio of 6:1 means that:", o:["Six molecules pass through the gas generator for every one that bypasses it", "Six molecules bypass the gas generator for every one that passes through it", "The fan produces six times the thrust of the gas generator", "Six percent of total airflow bypasses the gas generator"], a:1, r:"Six molecules bypass the gas generator for every one that goes through it.", ref:"Ch 4, EO 2.87"},
    {q:"Compared to a low bypass ratio engine, a high bypass ratio engine will have:", o:["A higher TSFC and better high-altitude performance", "A lower TSFC and greater takeoff weight capability", "A higher TSFC and shorter takeoff distance", "A lower TSFC and higher maximum airspeed"], a:1, r:"Higher bypass yields lower TSFC, greater takeoff weight, and shorter takeoff distance \u2014 but the high-end airspeed and altitude are more limited, so D is wrong.", ref:"Ch 4, EO 2.87"},
    {q:"The fan of a turbofan engine may be driven by:", o:["The compressor only", "A free/power turbine only", "Either the gas generator turbine or a free/power turbine", "The reduction gear box"], a:2, r:"The fan may be driven by the gas generator turbine (attached directly to the compressor) or by a free/power turbine.", ref:"Ch 4, EO 2.81"},
    {q:"In a turboprop engine, approximately what percentage of total thrust is produced by the propeller?", o:["25 percent", "50 percent", "75 percent", "90 percent"], a:3, r:"The propeller produces approximately 90 percent; the exhaust gases produce about 10 percent.", ref:"Ch 4, EO 2.88"},
    {q:"The reduction gear box of a turboprop converts:", o:["Low RPM and low torque to high RPM and high torque", "High RPM and low torque to low RPM and high torque", "Low RPM and high torque to high RPM and low torque", "High RPM and high torque to low RPM and low torque"], a:1, r:"The RGB converts the high RPM/low torque of the gas generator to the low RPM/high torque needed for efficient propeller operation, keeping blade tips subsonic.", ref:"Ch 4, EO 2.89"},
    {q:"Within the torque meter assembly, the shaft that twists under load and produces the torsional deflection is the:", o:["Reference shaft (outer)", "Torque shaft (inner)", "Compressor extension shaft", "Coaxial main drive shaft"], a:1, r:"The torque shaft is the inner shaft; it carries the propeller load and produces torsional deflection. The reference shaft (outer) does not twist and provides the reference.", ref:"Ch 4, EO 2.90"},
    {q:"The beta range of turboprop operation:", o:["Is the flight range, from flight idle to full power", "Is used only during ground operations, from flight idle to max reverse", "Allows the FCU to govern blade angle automatically in flight", "Is used to feather the propeller in flight"], a:1, r:"Beta is ground operations only, flight idle to max reverse, with the PCL mechanically connected to the pitch change assembly. Alpha is the flight range.", ref:"Ch 4, EO 2.91"},
    {q:"In a turboshaft engine, the propulsive energy produced by the exhaust is:", o:["Approximately 25 percent", "Approximately 10 percent", "Negligible", "Approximately 40 to 70 percent"], a:2, r:"In the turboshaft, propulsive energy from the exhaust is negligible; the free/power turbine extracts virtually all remaining energy as shaft horsepower. B (10 percent) is the turboprop figure.", ref:"Ch 4, EO 2.92"},
    {q:"A free/power turbine is best described as a turbine that is:", o:["Mechanically connected to the compressor and located forward of the burner", "Not mechanically connected to the compressor and located aft of the gas generator turbines", "Driven directly by the reduction gear box", "Used only on turbojet engines equipped with afterburner"], a:1, r:"A free turbine is not mechanically connected to the compressor and sits aft of the gas generator turbines.", ref:"Ch 4, EO 2.93"},
    {q:"Pascal's Law states that pressure applied to a confined liquid is:", o:["Transmitted with a proportional loss over distance", "Transmitted equally in all directions without loss, acting with equal force on equal surfaces", "Dependent upon the shape of the container", "Multiplied in proportion to the length of the connecting tube"], a:1, r:"Pressure applied to a confined liquid is transmitted equally in all directions without loss of pressure and acts with equal force on equal surfaces; container shape is irrelevant.", ref:"Ch 5, EO 2.94"},
    {q:"In a hydraulic system, force multiplication is gained at the expense of:", o:["System pressure", "Fluid volume", "Linear displacement (distance traveled)", "Fluid temperature"], a:2, r:"Linear displacement or distance traveled is exchanged for the gain in force, and is inversely proportional to the multiplied force.", ref:"Ch 5, EO 2.95"},
    {q:"An input piston with an area of 2 square inches has a 20-pound force applied to it. What force is produced on an output piston with an area of 20 square inches?", o:["20 pounds", "100 pounds", "200 pounds", "400 pounds"], a:2, r:"20 lb \u00f7 2 in\u00b2 = 10 PSI. 10 PSI \u00d7 20 in\u00b2 = 200 pounds.", ref:"Ch 5, EO 2.95"},
    {q:"Many military aircraft hydraulic systems operate near:", o:["300 PSI", "1,000 PSI", "3,000 PSI", "10,000 PSI"], a:2, r:"Many hydraulic systems operate near 3,000 PSI.", ref:"Ch 5, EO 2.96"},
    {q:"Which of the following is NOT a function of the hydraulic reservoir?", o:["Store fluid and replenish leakage losses", "Allow air bubbles to be purged", "Serve as an overflow basin for thermal expansion", "Multiply the force applied by the pump"], a:3, r:"The reservoir stores fluid, replenishes leakage, acts as an overflow basin for thermal expansion, purges air bubbles, and separates foreign matter. Force multiplication is the function of the system (the piston areas), not the reservoir.", ref:"Ch 5, EO 2.96"},
    {q:"During normal operation, a pressurized hydraulic reservoir receives its pressurization from:", o:["Engine bleed air", "The accumulator's nitrogen chamber", "A dedicated electric compressor", "Ram air from the inlet duct"], a:0, r:"During normal operation the pressurizing air source is engine bleed air (pressurized reservoirs may alternatively use hydraulic system pressure).", ref:"Ch 5, EO 2.96"},
    {q:"A pressure regulator or unloader valve is always used in conjunction with which type of pump?", o:["Hand pump", "Variable displacement pump", "Constant displacement pump", "Electric-motor-driven pump only"], a:2, r:"The pressure regulator/unloader valve always works in conjunction with the constant displacement pump, since that pump delivers constant output regardless of system pressure.", ref:"Ch 5, EO 2.96"},
    {q:"Which hydraulic component absorbs pressure surges, supplements pump output under peak load, and stores fluid for emergency operation?", o:["Check valve", "Accumulator", "Relief valve", "Hydraulic fuse"], a:1, r:"All three are accumulator functions. The check valve (A) ensures one-way flow, the relief valve (C) limits maximum pressure, and the fuse (D) isolates leaks.", ref:"Ch 5, EO 2.96"},
    {q:"The purpose of the hydraulic fuse is to:", o:["Limit maximum system pressure to prevent seal damage", "Prevent excessive fluid loss from a leak while permitting operation of the remaining subsystems", "Ensure one-way flow of fluid from the pump", "Illuminate a cockpit warning light when pressure drops"], a:1, r:"The hydraulic fuse detects ruptures or leak-producing failures and prevents excessive fluid loss while permitting operation of the remaining subsystem. A describes the relief valve; C the check valve; D the pressure switch.", ref:"Ch 5, EO 2.96"},
    {q:"A selector control valve is used to:", o:["Convert fluid pressure into mechanical motion", "Direct fluid under pressure to the desired working port of an actuator", "Divert excess pump flow back to the reservoir", "Prevent back flow of system pressure during shutdown"], a:1, r:"The selector valve directs pressurized fluid to the desired working port of an actuator and simultaneously directs return fluid to the reservoir. A describes the actuator itself.", ref:"Ch 5, EO 2.96"},
    {q:"Most modern military aircraft primarily use AC-powered components because AC components are:", o:["Heavier but more powerful", "Lightweight, simple, and reliable", "Simpler to install but require more maintenance", "Capable of operating at lower voltages with higher current"], a:1, r:"AC requires less current due to higher voltage and a ground neutral system, allowing smaller wiring and lighter components; AC components are lightweight, simple, and reliable.", ref:"Ch 6, EO 2.97"},
    {q:"What provides a constant rotational input speed to the generator regardless of engine RPM?", o:["Transformer rectifier", "Inverter", "Constant speed drive (CSD)", "Accessory gear box"], a:2, r:"The constant speed drive is the hydro-mechanical linkage between the engine and generator ensuring constant rotational input and therefore steady voltage output. Controlling-component check: the accessory gear box (D) is where the generator is coupled, not what regulates its input speed.", ref:"Ch 6, EO 2.98"},
    {q:"A transformer rectifier (TR) transforms:", o:["DC power into AC power", "AC power into DC power", "Mechanical energy into electrical energy", "High-voltage AC into low-voltage AC"], a:1, r:"The TR transforms AC power into DC power.", ref:"Ch 6, EO 2.98"},
    {q:"An inverter is used on an AC-equipped aircraft primarily as:", o:["The main source of AC power", "A backup means of providing AC from the battery should the AC generator fail", "A means of charging the battery from the essential bus", "A means of converting AC to DC for avionics"], a:1, r:"On an AC-system aircraft the inverter is primarily a backup, providing AC from the battery if the AC generator fails. On DC systems it powers AC equipment.", ref:"Ch 6, EO 2.98"},
    {q:"Which bus routes power to equipment required for flight safety, such as the primary attitude gyro?", o:["Primary bus", "Monitor bus", "Essential bus", "Starter bus"], a:2, r:"Essential bus: flight safety equipment. Primary: mission equipment. Monitor/secondary: convenience circuits. Starter: engine start circuits.", ref:"Ch 6, EO 2.98"},
    {q:"Which of the following provides an automatic means of interrupting electrical power?", o:["Switches only", "Circuit breakers and fuses", "Warning lights", "The transformer rectifier"], a:1, r:"Circuit breakers interrupt power automatically (and can be operated manually); fuses provide automatic circuit protection. Switches provide manual control only.", ref:"Ch 6, EO 2.98"},
  ]
},
{
  name: "Chapters 6\u20139 \u2014 Electrical, Fuel, Lube & Starts",
  desc: "Chapter-focused review: Electrical, Fuel, Lubrication, and Accessory/Starter/Ignition.",
  questions: [
    {q:"A generator is a device that transforms:", o:["Electrical energy into mechanical energy", "Mechanical energy into electrical energy", "Alternating current into direct current", "Direct current into alternating current"], a:1, r:"A generator transforms mechanical energy (input) into electrical energy (output).", ref:"Ch 6, EO 2.98"},
    {q:"The aircraft battery provides direct current primarily for:", o:["Powering the primary bus during cruise", "Emergency power should the generators fail, and for engine starting", "Driving the constant speed drive", "Powering AC equipment through the transformer rectifier"], a:1, r:"Battery DC voltage is primarily emergency power should the generators fail, and for starting the engines.", ref:"Ch 6, EO 2.98"},
    {q:"With a main generator failure, which bus or buses will stay on the line?", o:["Primary and monitor buses", "Starter bus only", "DC and AC essential buses", "All buses, powered by the CSD"], a:2, r:"The DC and AC essential buses remain on the line.", ref:"Ch 6, EO 2.98"},
    {q:"An Auxiliary Power Unit (APU) is best described as:", o:["A ground cart supplying regulated external power", "A small, independent gas-turbine engine driving a backup generator through a gearbox", "A backup battery pack located in the aircraft nose", "A hydraulically driven emergency generator"], a:1, r:"The APU is a small, independent gas-turbine engine providing power through a driveshaft to a gearbox that turns a backup generator. A describes ground Support Equipment.", ref:"Ch 6, EO 2.98"},
    {q:"Volatility is defined as:", o:["The minimum temperature at which a fuel emits enough vapor to ignite momentarily", "The measurement of a liquid's ability to convert to a vaporous state", "The resistance of a fluid to flow", "The heat energy content of a fuel per gallon"], a:1, r:"Volatility is the measurement of a liquid's ability to convert to a vaporous state. A is the definition of flash point.", ref:"Ch 7, EO 2.99"},
    {q:"An increase in fuel temperature will cause what change to volatility and flash point?", o:["Volatility increases; flash point decreases", "Volatility increases; flash point remains constant", "Volatility decreases; flash point increases", "Both remain constant"], a:1, r:"Increasing fuel temperature increases the vapors released and therefore volatility; flash point always remains constant (it is a fixed property of the fuel). Trap: the volatility rating and flash point are inversely related \u2014 but heating a given fuel does not change its flash point.", ref:"Ch 7, EO 2.101"},
    {q:"JP-5 is the primary Navy jet fuel because it:", o:["Has a low flash point of -35 \u00b0F, allowing easier starting", "Has low volatility and a high flash point of 140 \u00b0F, meeting shipboard storage requirements", "Is a wide-cut blend with naphtha fractions for cold weather starts", "Has the same flash point as Avgas"], a:1, r:"JP-5 has low volatility and a high flash point of 140 \u00b0F, meeting Naval safety requirements for shipboard storage. A describes JP-4 (-35 \u00b0F).", ref:"Ch 7, EO 2.102"},
    {q:"The boost pump is an integral unit composed of a:", o:["Positive displacement gear pump and hydraulic motor", "Centrifugal pump and electric motor", "Rotary vane pump and engine-driven shaft", "Piston pump and pneumatic actuator"], a:1, r:"The boost pump is an integral unit composed of a centrifugal pump and electric motor, submerged in the fuel tanks.", ref:"Ch 7, EO 2.103"},
    {q:"The primary reason a boost pump is included in the aircraft fuel system is to:", o:["Meter fuel to the combustion section", "Prevent aeration of the fuel supply, avoiding vapor lock or cavitation of the engine-driven pump", "Preheat fuel and remove ice crystals", "Drain the manifolds upon engine shutdown"], a:1, r:"A critical function is preventing aeration of the fuel supply, which could induce vapor lock or cavitation of the engine-driven pump.", ref:"Ch 7, EO 2.103"},
    {q:"Which component is the \"brain\" of the engine fuel system, sending metered fuel for starting, acceleration, deceleration, and steady state operation?", o:["Engine-driven pump", "Pressurizing and dump valve", "Fuel control unit", "Afterburner fuel control unit"], a:2, r:"The FCU is the \"brain\" of the engine fuel system. The afterburner FCU (D) meters fuel to the afterburner spray bars only.", ref:"Ch 7, EO 2.103"},
    {q:"Which of the following is NOT one of the four inputs processed by the FCU?", o:["Compressor inlet temperature", "Compressor RPM", "Turbine temperature", "Fuel tank quantity"], a:3, r:"The four inputs are compressor inlet temperature (ambient air density), RPM (compressor speed), turbine temperature (ITT), and PCL position. Fuel quantity is not an FCU input.", ref:"Ch 7, EO 2.103"},
    {q:"In the aircraft fuel system, metered fuel begins:", o:["At the outlet of the boost pump", "At the outlet of the engine-driven pump", "After the FCU", "At the fuel manifold"], a:2, r:"Metered fuel begins after the FCU.", ref:"Ch 7, EO 2.103"},
    {q:"Compared to the secondary manifold, the primary fuel manifold has:", o:["Larger diameter tubes, allowing greater fuel volume at high power", "Smaller diameter tubes, permitting high pressure and atomization during starting and altitude idling", "Identical tubes, differing only in position on the engine", "Smaller diameter tubes, used exclusively for afterburner fuel"], a:1, r:"The primary manifold's smaller tubes let fuel reach comparatively high pressure and atomization during starting and altitude idling; the secondary manifold takes over once RPM raises fuel pressure to a preset level. Naming conflict reminder: this primary/secondary pair is fuel, unrelated to the 25%/75% primary/secondary air split in the burner (Ch 2).", ref:"Ch 7, EO 2.103"},
    {q:"During engine shutdown, the pressurizing and dump (P&D) valve positions are:", o:["Dump valve closed, pressurizing valve open", "Both valves closed", "Dump valve open, pressurizing valve closed", "Both valves open"], a:2, r:"Start: both closed. Normal operation: dump closed, pressurizing open. Shutdown: dump open (draining manifolds), pressurizing closed.", ref:"Ch 7, EO 2.103"},
    {q:"Failure of the P&D valve to drain residual fuel from the manifolds after shutdown may result in:", o:["A compressor stall on the next flight", "An engine fire upon shutdown or a hot start on the next attempt", "Loss of afterburner capability", "Immediate flameout"], a:1, r:"Undrained residual fuel can cause an engine fire on shutdown or a hot start on the next attempt, plus carbon and gum deposits clogging manifolds and nozzles.", ref:"Ch 7, EO 2.103"},
    {q:"Military Rated Thrust (MRT) is:", o:["Thrust at maximum continuous turbine temperature with no time limitation", "Thrust at maximum turbine temperature for a limited time, normally 30 minutes", "Thrust produced with the afterburner in operation", "Thrust measured at standard day conditions on a test stand"], a:1, r:"MRT is thrust at maximum turbine temperature for a limited time, normally 30 minutes. A is NRT; C is CRT.", ref:"Ch 7, EO 2.104"},
    {q:"The primary function of any lubricant is to:", o:["Dissipate heat from the combustion section", "Reduce friction caused by metal-to-metal contact", "Seal the bearing compartments against bleed air", "Prevent corrosion of accessory drive gears"], a:1, r:"The primary function of any lubricant is to reduce friction caused by metal-to-metal contact.", ref:"Ch 8, EO 2.105"},
    {q:"Which statement about synthetic oil is correct?", o:["It may be freely mixed with petroleum base oils", "It has an unlimited shelf life", "It is corrosive and has a shelf life of approximately three years", "MIL-L-7808 is the most commonly used synthetic oil in current jet engines"], a:2, r:"Synthetic oil is very corrosive (damaging paint, O-rings, gaskets outside the system) and has a shelf life of approximately three years. Synthetics must never be mixed with petroleum base oils; MIL-L-23699 \u2014 not 7808 \u2014 is the current common oil.", ref:"Ch 8, EO 2.106"},
    {q:"Viscosity is defined as the property of a fluid that resists the force tending to cause the fluid to flow. Viscosity and temperature are:", o:["Directly related", "Inversely related", "Unrelated", "Related only above the flash point"], a:1, r:"Viscosity is inversely related to temperature: as temperature increases, viscosity decreases.", ref:"Ch 8, EO 2.107"},
    {q:"The most prevalent form of contamination in the lubrication system is:", o:["Carbon deposits from coking", "Sand and dirt from improper servicing", "Small metal particles from metal-to-metal contact", "Water condensation in the oil tank"], a:2, r:"The most prevalent form of contamination in all engines is the generation of small metal particles due to metal-to-metal contact.", ref:"Ch 8, EO 2.108"},
    {q:"The reservoir for a wet sump system is:", o:["A tank mounted in the airframe", "The accessory gear case, or a sump mounted to the bottom of it", "An integral part of the compressor case", "The scavenge subsystem manifold"], a:1, r:"The wet sump reservoir is either the accessory gear case or a sump mounted to the bottom of it \u2014 similar to an automobile. A describes the dry sump.", ref:"Ch 8, EO 2.108"},
    {q:"In a dry sump lubrication system, the three subsystems are:", o:["Pressure, scavenge, and breather pressurizing", "Pressure, return, and vent", "Supply, cooling, and filtration", "Pressure, scavenge, and relief"], a:0, r:"Pressure (supplies oil to main bearings and accessory drives), scavenge (removes oil through the coolers back to the tank), and breather pressurizing (minimizes oil leakage).", ref:"Ch 8, EO 2.108"},
    {q:"Scavenge pump elements have a greater pumping capacity than pressure elements in order to:", o:["Increase oil pressure at the bearings", "Prevent back pressure and the accumulation of oil in the bearing sumps", "Compensate for filter bypass losses", "Maintain sea level pressure in the oil tank"], a:1, r:"Greater scavenge capacity prevents back pressure in the system and the accumulation of hot oil in the bearing sumps.", ref:"Ch 8, EO 2.108"},
    {q:"The oil temperature gauge displays the temperature of the oil:", o:["As it leaves the oil pump", "Prior to entering the engine bearing compartments", "Inside the fuel-oil heat exchanger", "At the scavenge pump inlet"], a:1, r:"The oil temperature gauge displays oil temperature prior to entering the engine bearing compartments, and indicates the performance of the scavenge subsystem (which contains the coolers). The oil pressure gauge displays pump discharge pressure.", ref:"Ch 8, EO 2.108"},
    {q:"The oil temperature regulating valve is located at the _______ and directs the flow of return oil into the fuel-oil heat exchanger.", o:["Fuel exit of the fuel-oil cooler", "Oil entrance to the fuel-oil heat exchanger", "Inlet of the air-oil cooler", "Outlet of the pressure relief valve"], a:1, r:"The oil temperature regulating valve sits at the oil entrance to the fuel-oil heat exchanger; if no cooling is needed it stays closed and routes oil directly to the tank. Answer A is the location of the fuel temperature sensing switch.", ref:"Ch 8, EO 2.108"},
    {q:"The fuel temperature sensing switch, when it detects excessive fuel temperature, sends an electrical signal to:", o:["Close the oil temperature regulating valve", "Actuate the air-oil cooler doors", "Open the filter bypass valve", "Increase scavenge pump output"], a:1, r:"The fuel temperature sensing switch actuates the air-oil cooler doors, allowing air through the air-oil cooler. Pair these two deliberately: thermostatic/regulating valve = oil side, mechanical, controls flow through the fuel-oil cooler; sensing switch = fuel side, electrical, controls the air-oil cooler doors.", ref:"Ch 8, EO 2.108"},
    {q:"Interstage bleed air is:", o:["Used to drive air conditioning and cabin pressurization units", "Ducted overboard to ensure compressor stability, and is not used to drive accessories", "Extracted from the high pressure compressor for anti-ice", "Available at all thrust settings with steady volume and pressure"], a:1, r:"Interstage bleed air is ducted overboard to prevent compressor stall during low thrust operation. It is not used to drive accessories because it is unavailable at high thrust settings and lacks steady volume or pressure. A and C describe the high and low pressure bleed air systems.", ref:"Ch 9, EO 2.111"},
    {q:"The correct gas turbine engine starting sequence is:", o:["Fuel, ignition, compressor RPM", "Ignition, fuel, compressor RPM", "Compressor RPM (airflow), ignition, fuel", "Compressor RPM (airflow), fuel, ignition"], a:2, r:"The starter accelerates the compressor to establish airflow, then ignition is activated, then fuel is added. Sufficient airflow must exist first to prevent an explosion when the mixture ignites. Note: some legacy practice materials key this incorrectly \u2014 the Student Guide sequence is airflow \u2192 ignition \u2192 fuel.", ref:"Ch 9, EO 5.1"},
    {q:"A \"hung start\" is best described as:", o:["Exceeding the maximum allowable turbine temperature during start", "Turbine temperature continuing to rise while compressor RPM stabilizes below normal", "Compressor RPM stabilizing below normal with turbine temperature within limits", "A fuel-air mixture that fails to light off initially but may eventually ignite"], a:1, r:"Hung start: turbine temperature continues to rise and compressor RPM stabilizes below normal. A is a hot start, C is a false start, D is a wet start (the most dangerous).", ref:"Ch 9, EO 5.2"},
    {q:"Which ignitor plug operates at a cooler temperature, with a spark that tends to jump in an arc carrying it beyond the face of the chamber liner?", o:["Annular-gap plug", "Constrained-gap plug", "Constrained-annular plug", "High-tension surface-gap plug"], a:1, r:"The constrained-gap plug's spark jumps in an arc beyond the face of the chamber liner, so it operates cooler than the annular-gap plug. Note that most plugs are the annular-gap type \u2014 the question asks which runs cooler, not which is more common.", ref:"Ch 9, EO 5.5"},
  ]
},
{
  name: "Pumped & Dumped (Class Gouge)",
  desc: "56 questions converted from the NIFE 2025 'Pumped and Dumped' gouge deck. Class-sourced \u2014 not Student Guide-verified; rationales note where the gouge and SG differ.",
  questions: [
    {q:"What three properties are used in the production of thrust by the gas turbine engine?", o:["Pressure, temperature, and velocity", "Lift, weight, and drag", "Density, viscosity, and humidity", "RPM, torque, and horsepower"], a:0, r:"The deck lists pressure, temperature, and velocity as the three properties used in thrust production.", ref:"Ch 1 \u00b7 Gouge #10"},
    {q:"Per the gouge, the thrust equation is:", o:["T = M \u00d7 A", "T = P \u00d7 A", "T = \u00bd\u03c1V\u00b2", "T = F \u00f7 A"], a:0, r:"Thrust equals mass times acceleration (T = M \u00d7 A).", ref:"Ch 1 \u00b7 Gouge #13"},
    {q:"Which type of thrust is corrected for the effects of inlet airflow velocity and is the more realistic measurement of engine thrust?", o:["Gross thrust", "Net thrust", "Static thrust", "Military rated thrust"], a:1, r:"Gross thrust ignores inlet velocity and assumes standard day; net thrust corrects for inlet airflow velocity and is more realistic.", ref:"Ch 1 \u00b7 Gouge #12"},
    {q:"Using the TAPERD acronym, which combination results in INCREASED thrust production?", o:["Temperature decreased, altitude decreased, pressure increased, RPM increased, ram increased, density increased", "Temperature increased, altitude increased, pressure increased, RPM increased, ram increased, density decreased", "Temperature decreased, altitude increased, pressure decreased, RPM increased, ram decreased, density increased", "Temperature increased, altitude decreased, pressure increased, RPM decreased, ram increased, density increased"], a:0, r:"TAPERD: for better thrust \u2014 Temperature down, Altitude down, Pressure up, Engine RPM up, RAM up, Density up.", ref:"Ch 1 \u00b7 Gouge #15"},
    {q:"Which statement about the tachometer is correct?", o:["It indicates engine rotation speed in percent RPM but does NOT measure thrust", "It measures thrust directly in pounds", "It displays the pressure ratio between inlet and exhaust", "It indicates shaft horsepower for turboprops"], a:0, r:"The tachometer is calibrated in percent RPM and does not measure thrust \u2014 a favorite true/false trap in the deck.", ref:"Ch 1 \u00b7 Gouge #19"},
    {q:"Considering only the theoretical thrust relationship, if airspeed decreases, what happens to thrust?", o:["It increases \u2014 the two are inversely related", "It decreases proportionally", "It is unaffected by airspeed", "It increases only above 36,000 feet"], a:0, r:"The deck keys this inverse relationship: as airspeed (inlet velocity) decreases, theoretical thrust increases. Ram effect offsets this in practice.", ref:"Ch 1 \u00b7 Gouge #215"},
    {q:"The compressor is an ______ system, which means velocity and pressure are ______ related through it.", o:["Open; directly", "Closed; inversely", "Closed; directly", "Open; inversely"], a:0, r:"Because the compressor receives outside energy (an open system), velocity AND pressure both rise \u2014 directly related, increasing total pressure.", ref:"Ch 1 \u00b7 Gouge #216"},
    {q:"For supersonic inlet ducts, what is another term for the convergent-divergent design that handles compressible airflow?", o:["Variable geometry inlet duct", "Bellmouth inlet", "Ram recovery duct", "Divergent-only diffuser"], a:0, r:"The deck's term for the supersonic C-D inlet is the variable geometry inlet duct.", ref:"Ch 2 \u00b7 Gouge #21"},
    {q:"Which compressor is rugged, low cost, with good power output over a large RPM range \u2014 but requires a large front area and is impractical for multiple stages?", o:["Centrifugal flow compressor", "Axial flow compressor", "Axial-centrifugal flow compressor", "Dual spool axial compressor"], a:0, r:"Centrifugal: rugged, cheap, high pressure rise per stage; penalties are frontal area and no practical multi-staging.", ref:"Ch 2 \u00b7 Gouge #26"},
    {q:"The OHIO acronym gives the dual spool axial flow order. What is it?", o:["LOw pressure compressor \u2192 High pressure compressor \u2192 hIgh pressure turbine \u2192 lOw pressure turbine", "High pressure compressor \u2192 lOw pressure compressor \u2192 hIgh pressure turbine \u2192 lOw pressure turbine", "LOw pressure compressor \u2192 hIgh pressure turbine \u2192 High pressure compressor \u2192 lOw pressure turbine", "LOw pressure turbine \u2192 hIgh pressure turbine \u2192 High pressure compressor \u2192 lOw pressure compressor"], a:0, r:"OHIO: LOw compressor, High compressor, hIgh turbine, lOw turbine \u2014 front to back.", ref:"Ch 2 \u00b7 Gouge #33"},
    {q:"In an axial-centrifugal flow compressor, what does each portion contribute?", o:["Axial: straight-through ram efficiency and multiple stages for high pressure; Centrifugal: significantly increases pressure per stage", "Axial: pressure per stage; Centrifugal: straight-through flow", "Axial: reduced frontal area; Centrifugal: supersonic airflow capability", "Axial: bleed air supply; Centrifugal: FOD resistance"], a:0, r:"The hybrid pairs axial straight-through efficiency and staging with the centrifugal section's big per-stage pressure rise.", ref:"Ch 2 \u00b7 Gouge #35"},
    {q:"Secondary air (75% of burner airflow) provides which three things?", o:["Cooling the thin walls, controlling the flame, and afterburner operations", "Combustion, ignition, and cooling", "Anti-ice, cabin pressurization, and cooling", "Flame control, thrust augmentation, and fuel atomization"], a:0, r:"The deck's three: cool the thin walls, control the flame, and support afterburner ops.", ref:"Ch 2 \u00b7 Gouge #44"},
    {q:"The M.F.C.B. memory aid ('My Flame Can't Blow-out') covers the four combustion chamber design goals. Which list is correct?", o:["Minimize pressure decrease; flame must not blow out; combustion efficiency must remain high; burning complete before the turbine section", "Maximize pressure increase; flame must self-sustain; cooling must be complete; burning complete before the nozzle", "Minimize temperature; flame contained in cans; combustion staged; burning complete before the compressor", "Minimize weight; flame visible; combustion lean; burning complete before the afterburner"], a:0, r:"MFCB: Minimize pressure decrease, Flame must not blow out, Combustion efficiency high, Burning complete before the turbine.", ref:"Ch 2 \u00b7 Gouge #45"},
    {q:"Which combustion chamber can contain its own fuel nozzle, burner lining, and casing \u2014 strong and easy to maintain, but with greater pressure loss and cold spots on the turbine?", o:["Can", "Annular", "Can-annular", "Radial"], a:0, r:"The can type is self-contained and maintainable at the cost of pressure loss and uneven heat (cold spots).", ref:"Ch 2 \u00b7 Gouge #47"},
    {q:"The turbine section transforms what percentage of the heat energy from the combustion chamber into mechanical energy, leaving how much for thrust?", o:["75% to mechanical energy; 25% for thrust", "25% to mechanical energy; 75% for thrust", "50% each", "90% to mechanical energy; 10% for thrust"], a:0, r:"75% drives the compressor and accessory gearbox; 25% remains for thrust. Don't transpose with the burner's 25/75 air split.", ref:"Ch 2 \u00b7 Gouge #52"},
    {q:"What is the highest-stressed section of the gas turbine engine, and at roughly what temperature does it operate?", o:["The turbine section, ~2,000 \u00b0F", "The combustion chamber, ~3,500 \u00b0F", "The compressor, ~1,200 \u00b0F", "The exhaust section, ~1,500 \u00b0F"], a:0, r:"The turbine is the highest-stressed section, operating around 2,000 \u00b0F.", ref:"Ch 2 \u00b7 Gouge #55"},
    {q:"The three parts of the exhaust section are:", o:["Exhaust outer duct, exhaust inner duct, and radial hollow struts", "Tailpipe, nozzle, and afterburner", "Inner cone, spray bars, and flame holder", "Outer duct, screech liner, and turkey feathers"], a:0, r:"Outer duct, inner duct, and the radial hollow struts.", ref:"Ch 2 \u00b7 Gouge #58"},
    {q:"Of the three afterburner ignition methods, which is the most common?", o:["Spark ignition", "Torch ignition (pilot light)", "Hot stream ignition", "Glow plug ignition"], a:0, r:"Spark ignition is most common; torch (pilot light) and hot stream are the other two. Glow plug is not one of the three.", ref:"Ch 2 \u00b7 Gouge #62"},
    {q:"\u201cTurkey feathers\u201d is another name for the:", o:["Variable exhaust nozzle", "Screech liner", "Flame holder", "Radial hollow struts"], a:0, r:"Turkey feathers = the variable exhaust nozzle used for afterburner operations.", ref:"Ch 2 \u00b7 Gouge #67"},
    {q:"The basic components of the reciprocating engine are remembered as:", o:["4 C's, 2 V's, 1 P", "3 C's, 3 V's, 2 P's", "4 V's, 2 C's, 1 R", "5 C's, 1 V, 1 P"], a:0, r:"Four C's, two V's, one P \u2014 the deck's counting mnemonic for recip components.", ref:"Ch 2 \u00b7 Gouge #68"},
    {q:"Which list of compressor stall indications matches the gouge?", o:["Mild pulsations, engine vibration with noise (popping/banging), ITT increase, RPM decay, fluctuating gauges", "ITT decrease, RPM increase, steady gauges, silence", "Fuel flow increase only", "Oil pressure drop with EGT decrease"], a:0, r:"All five: pulsations, vibration/noise, ITT rise, RPM decay, fluctuating gauges.", ref:"Ch 3 \u00b7 Gouge #73"},
    {q:"The V2F2 acronym lists the four mechanical malfunctions that can cause a compressor stall. They are:", o:["Variable inlet guide vane/stator vane failure, Variable exhaust nozzle failure, FCU failure, FOD", "Valve failure, Vane failure, Fuel leak, Fire", "Variable geometry failure, Vibration, FOD, Flameout", "Vane failure, Velocity loss, FCU failure, Fan damage"], a:0, r:"V2F2: the two V's are variable IGV/stator vanes and variable exhaust nozzle; the two F's are FCU failure and FOD.", ref:"Ch 3 \u00b7 Gouge #75"},
    {q:"The D.A.R.E. acronym covers the four airflow distortions that can cause a compressor stall. They are:", o:["Deficiency of air velocity/volume from atmospheric conditions, Abrupt attitude change, Rapid throttle movement, Encountering air turbulence", "Density loss, Altitude increase, RPM decay, Exhaust blockage", "Downdrafts, Angle of attack, Ram loss, Engine wear", "Deceleration, Asymmetric thrust, Rain ingestion, Erosion"], a:0, r:"DARE: Deficiency of air velocity/volume, Abrupt attitude change, Rapid throttle movement, Encountering turbulence.", ref:"Ch 3 \u00b7 Gouge #79"},
    {q:"Pilots reduce the possibility of a compressor stall by avoiding 'F.A.M.E.' Which is the correct expansion?", o:["Flight through severe weather/turbulence, Abrupt attitude changes, (failing to) Maintain prescribed minimums, Erratic or abrupt PCL movement", "Fast climbs, Aggressive banking, Maximum power, Extended idle", "Formation flight, Aerobatics, Minimum fuel, Excess airspeed", "Flying low, Accelerating quickly, Manual fuel control, Engine overtemp"], a:0, r:"FAME: severe weather/turbulence, abrupt attitude changes, maintain prescribed minimums, erratic PCL movement.", ref:"Ch 3 \u00b7 Gouge #76"},
    {q:"Which engine has a high TSFC at low altitude/airspeed but the LIGHTEST specific weight per pound of thrust produced?", o:["Turbojet", "Turbofan", "Turboprop", "Turboshaft"], a:0, r:"The turbojet: thirsty down low, but lightest per pound of thrust.", ref:"Ch 4 \u00b7 Gouge #84"},
    {q:"What are the exhaust and mechanical thrust percentages for a turbojet?", o:["Exhaust 100% / Mechanical 0%", "Exhaust 70% / Mechanical 30%", "Exhaust 40% / Mechanical 60%", "Exhaust 10% / Mechanical 90%"], a:0, r:"All turbojet thrust is exhaust; none is mechanical.", ref:"Ch 4 \u00b7 Gouge #86"},
    {q:"Per the gouge, what are the thrust splits for LOW bypass and HIGH bypass turbofans (exhaust/mechanical)?", o:["Low bypass: 70/30; High bypass: 40/60", "Low bypass: 40/60; High bypass: 70/30", "Both: 50/50", "Low bypass: 90/10; High bypass: 10/90"], a:0, r:"Low bypass TF: exhaust 70%, mech 30%. High bypass: exhaust 40%, mech 60%. (The Student Guide states this as fan 30\u201360% / exhaust 40\u201370% \u2014 same idea as ranges.)", ref:"Ch 4 \u00b7 Gouge #90"},
    {q:"The turboprop propeller assembly is described by which four characteristics?", o:["Hydraulically controlled, constant speed, full feathering, and reversible", "Electrically controlled, variable speed, non-feathering, fixed pitch", "Pneumatically controlled, constant speed, auto-feathering, reversible", "Mechanically controlled, two-speed, full feathering, non-reversible"], a:0, r:"Hydraulically controlled, constant speed, full feathering, reversible.", ref:"Ch 4 \u00b7 Gouge #95"},
    {q:"Which component of the turboprop propeller assembly changes the blade angle?", o:["Pitch change / dome assembly", "Hub assembly", "Blade assembly", "Reduction gear box"], a:0, r:"The pitch change/dome assembly changes blade angle; the hub and blade assemblies are the other two components.", ref:"Ch 4 \u00b7 Gouge #96"},
    {q:"What must a turboshaft engine have?", o:["A free/power turbine, mechanically independent of the gas generator", "A ducted fan", "A reduction gear box driven directly by the compressor", "An afterburner section"], a:0, r:"A turboshaft is gas generator + free/power turbine; the free turbine is mechanically independent.", ref:"Ch 4 \u00b7 Gouge #103"},
    {q:"In relation to Pascal's Law, the equations for force and pressure are:", o:["F = P \u00d7 A and P = F \u00f7 A", "F = P \u00f7 A and P = F \u00d7 A", "F = A \u00f7 P and P = A \u00f7 F", "F = M \u00d7 A and P = \u00bd\u03c1V\u00b2"], a:0, r:"Force = pressure \u00d7 area; pressure = force \u00f7 area (PSI).", ref:"Ch 5 \u00b7 Gouge #107"},
    {q:"Which hydraulic system supplies fluid pressure for flight controls ONLY?", o:["Power control system", "Utility system", "Essential system", "Primary system"], a:0, r:"Power control system = flight controls only; the utility system does flight controls AND utility items (gear, flaps, brakes).", ref:"Ch 5 \u00b7 Gouge #112"},
    {q:"Which statement about hydraulic power pumps is correct?", o:["A variable displacement pump ('smart pump') regulates fluid volume to system demand; a constant displacement pump must incorporate a pressure regulator/unloader valve", "Both pump types require an unloader valve", "A constant displacement pump self-regulates its output", "The hand pump is the primary pressure source in flight"], a:0, r:"The smart pump matches demand; constant displacement pumps deliver constant output and therefore need a pressure regulator/unloader valve. The hand pump is for emergencies.", ref:"Ch 5 \u00b7 Gouge #116"},
    {q:"Which hydraulic valve allows one-way flow, works in tandem with the accumulator, and maintains partial system pressure if the hydraulic pump fails?", o:["Check valve", "Pressure relief valve", "Selector control valve", "Hydraulic fuse"], a:0, r:"The check valve \u2014 one-way flow, paired with the accumulator, holds partial pressure on pump failure.", ref:"Ch 5 \u00b7 Gouge #119"},
    {q:"Per the gouge's S.E.A.S. acronym, the accumulator provides:", o:["Shock absorption, Emergency use, Assistance in peak operations, and Shutdown system pressure maintenance", "Storage, Evaporation control, Aeration, and Sealing", "Surge protection, Energy generation, Actuation, and Steering", "Shock absorption, Electrical backup, Air separation, and Storage"], a:0, r:"SEAS: Shock absorber, Emergency use, Assists peak ops, Shutdown pressure maintenance (with the check valve).", ref:"Ch 5 \u00b7 Gouge #120"},
    {q:"How many sources of AC and DC electricity are there, and what are they?", o:["AC: 2 (alternator, inverter); DC: 3 (generator, battery, transformer-rectifier)", "AC: 3 (alternator, inverter, TR); DC: 2 (generator, battery)", "AC: 2 (generator, battery); DC: 3 (alternator, inverter, TR)", "AC: 1 (alternator); DC: 1 (battery)"], a:0, r:"Two AC sources: alternator and inverter. Three DC sources: generator, battery, transformer-rectifier.", ref:"Ch 6 \u00b7 Gouge #126"},
    {q:"Per the gouge, the essential bus powers flight safety equipment such as:", o:["The primary attitude gyro and IFF", "Radar and targeting pods", "Cabin lighting and galley power", "The engine starter motor"], a:0, r:"Essential = flight safety (attitude gyro, IFF). Primary = mission (radar); monitor/secondary = convenience; starter = engine start.", ref:"Ch 6 \u00b7 Gouge #131"},
    {q:"What is the difference between a circuit breaker and a fuse in an overload?", o:["A circuit breaker 'pops out' to prevent damage and can be reset; a fuse immediately and completely stops operation", "A fuse can be reset in flight; a breaker cannot", "Both must be replaced after any overload", "A breaker provides manual control only; a fuse provides both manual and automatic"], a:0, r:"Breakers pop and are resettable; fuses stop current completely and must be replaced.", ref:"Ch 6 \u00b7 Gouge #135"},
    {q:"Which statement about Avgas is correct?", o:["Avgas 100 is high lead and dyed green; Avgas 100LL is low lead and dyed blue", "Avgas 100 is low lead and dyed blue; Avgas 100LL is high lead and dyed green", "Both are dyed red and differ only in octane", "Avgas 100LL is unleaded and clear"], a:0, r:"100 = high lead, green. 100LL = low lead, blue.", ref:"Ch 7 \u00b7 Gouge #139"},
    {q:"Which jet fuel is used by the Air Force and NATO?", o:["JP-8", "JP-5", "JP-4", "Avgas 100LL"], a:0, r:"JP-8 is the Air Force/NATO fuel; JP-5 is the Navy's shipboard-safe primary fuel.", ref:"Ch 7 \u00b7 Gouge #141"},
    {q:"Which thrust rating is used for afterburner operations and has no time or temperature limit per the gouge?", o:["Combat rated thrust", "Military rated thrust", "Normal rated thrust", "Gross rated thrust"], a:0, r:"CRT = afterburner ops, no time/temp limit. MRT = max ITT for 30 minutes; NRT = cruise, no time limit.", ref:"Ch 7 \u00b7 Gouge #142"},
    {q:"Where is the daily fuel sample taken?", o:["The low point drain valve within the fuel tank", "The fuel-oil heat exchanger outlet", "The boost pump inlet screen", "The P&D valve drain line"], a:0, r:"Daily samples come from the tank's low point drain valve, where water and contaminants settle.", ref:"Ch 7 \u00b7 Gouge #147"},
    {q:"Why is the boost pump / fuel pressure gauge / engine-driven pump relationship important?", o:["A failed boost pump (shown by a pressure drop on the gauge) can cause cavitation or failure of the engine-driven pump, ultimately risking a flameout", "The boost pump meters fuel; the gauge displays PPH; the engine-driven pump drains the manifolds", "The engine-driven pump supplies the boost pump, and gauge failure causes fuel starvation", "They share a common electrical bus and fail together"], a:0, r:"Boost pump feeds the engine-driven (main) pump under pressure; losing it invites cavitation, pump failure, and possible flameout.", ref:"Ch 7 \u00b7 Gouge #151"},
    {q:"The FCU generates fuel requirements based on four inputs \u2014 the C.R.I.P. acronym. They are:", o:["Compressor inlet temperature, RPM (compressor speed), ITT (turbine temp), PCL position", "CG position, RPM, inlet pressure, propeller pitch", "Compressor RPM, ram air, IGV angle, power lever friction", "CIT, RPM, ITT, and fuel tank quantity"], a:0, r:"CRIP: CIT, RPM, ITT, PCL position. Fuel quantity is NOT an FCU input.", ref:"Ch 7 \u00b7 Gouge #154"},
    {q:"The FCU sends metered fuel for S.A.D.S., which stands for:", o:["Starting, Acceleration, Deceleration, Stabilized operations", "Start, Afterburner, Descent, Shutdown", "Supply, Atomization, Distribution, Spray", "Starting, Altitude, Descent, Stopping"], a:0, r:"SADS: starting, acceleration, deceleration, and stabilized (steady state) operation.", ref:"Ch 7 \u00b7 Gouge #153"},
    {q:"Which flight operations do the primary and secondary fuel manifolds support?", o:["Primary: starting and idle; Secondary: continuous operations after start", "Primary: continuous operations; Secondary: starting only", "Primary: afterburner; Secondary: cruise", "Both supply all phases equally"], a:0, r:"Primary handles starting/idle (small tubes, high atomization); secondary takes over for continuous operations after start.", ref:"Ch 7 \u00b7 Gouge #157"},
    {q:"Which statement about sump systems is correct?", o:["The wet sump is internal to the engine and harder to cool; the dry sump is external with better oil cooling", "The dry sump is internal and harder to cool", "Both are external to the engine", "The wet sump uses three subsystems: pressure, scavenge, breather"], a:0, r:"Wet = internal, difficult to cool. Dry = external tank, better cooling, and it's the dry sump that has the three subsystems.", ref:"Ch 8 \u00b7 Gouge #166"},
    {q:"What are flapper valves, and when do they close?", o:["Oil tank valves that are normally open but close during deceleration or inverted flight to trap oil at the bottom of the tank, keeping the weighted swivel immersed", "Bypass valves on the oil filter that close when the filter clogs", "Breather valves that close at altitude", "Fuel valves that close at engine shutdown"], a:0, r:"Flapper valves trap oil during deceleration/inverted flight so the gravity-positioned weighted swivel stays immersed in oil.", ref:"Ch 8 \u00b7 Gouge #171"},
    {q:"The oil pressure gauge and oil temperature gauge indicate the performance of which subsystems, respectively?", o:["Pressure subsystem and scavenge subsystem", "Scavenge subsystem and pressure subsystem", "Breather subsystem and pressure subsystem", "Both indicate the breather subsystem"], a:0, r:"Oil pressure gauge (pump discharge pressure) = pressure subsystem; oil temperature gauge (oil before the bearings) = scavenge subsystem.", ref:"Ch 8 \u00b7 Gouge #173"},
    {q:"In the fuel-oil heat exchanger relationship, what does each fluid need?", o:["Oil needs to be cooled; fuel needs to be heated", "Oil needs to be heated; fuel needs to be cooled", "Both need cooling", "Both need heating"], a:0, r:"The FOHX swaps heat both directions at once: hot oil is cooled, cold fuel is warmed.", ref:"Ch 8 \u00b7 Gouge #176"},
    {q:"A lubrication 'squeeze film' is the result of:", o:["Proper oil viscosity (which is why engine oil temperature and pressure must be monitored)", "Excessive oil pressure", "Fuel contamination of the oil", "Bleed air in the bearing sumps"], a:0, r:"Proper viscosity produces the squeeze film protecting the bearings \u2014 lose temp/pressure monitoring and you can lose it.", ref:"Ch 8 \u00b7 Gouge #217"},
    {q:"Bleed air is ducted as a source of power for operating which of the following?", o:["Air conditioning units, cockpit pressurization, and engine anti-ice", "Tachometers, hydraulic pumps, and generators", "The FCU and P&D valve", "Navigation lights and radios"], a:0, r:"Bleed-air-driven accessories: AC units, cockpit pressurization, engine anti-ice. Tach/hyd pumps/generators are mechanically driven.", ref:"Ch 9 \u00b7 Gouge #185"},
    {q:"The low pressure compressor is also identified as ______ and its speed is read on the ______.", o:["N1; tachometer", "N2; torquemeter", "N1; EPR gauge", "N2; ITT gauge"], a:0, r:"The LP compressor is N1, measured through the tachometer.", ref:"Ch 9 \u00b7 Gouge #191"},
    {q:"Which starter type is most common on LARGE gas turbine engines?", o:["The air turbine (pneumatic) starter", "The DC electric motor starter", "The cartridge starter", "The hand crank"], a:0, r:"Air turbine/pneumatic starters serve large GTEs; DC electric motors are most common on small GTEs \u2014 and both types need electricity to start the engine.", ref:"Ch 9 \u00b7 Gouge #204"},
    {q:"Aircraft use High Heat Intensity Capacitor Ignition Systems because they prevent the igniters from:", o:["Fouling/coking, which can lead to a misfire", "Overheating the combustion liner", "Arcing beyond the chamber liner", "Draining the battery during start"], a:0, r:"The high-voltage, exceptionally hot spark keeps igniters from fouling/coking and lights low-volatility fuel at all temps and altitudes.", ref:"Ch 9 \u00b7 Gouge #206"},
    {q:"Which spark ignitor plug protrudes slightly into the chamber and is the MOST COMMON type?", o:["Annular gap", "Constrained gap", "Surface gap", "Extended electrode"], a:0, r:"Annular gap = most common, protrudes slightly. Constrained gap = arcs beyond the liner face and runs cooler \u2014 the exam asks both directions.", ref:"Ch 9 \u00b7 Gouge #207"},
  ]
},
];
